  return (
    <header className="bg-white px-6 pt-6 pb-4 border-b border-gray-100 flex flex-col gap-4">
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            Minha Lista
            {isPremium && (
              <span className="bg-amber-100 text-amber-700 text-[10px] font-bold px-1.5 py-0.5 rounded uppercase tracking-tighter">Premium</span>
            )}
