import React, { useRef, useState, useEffect } from 'react';
import { ShoppingItem } from '../types';

interface ItemCardProps {
  item: ShoppingItem;
  onUpdate: (updates: Partial<ShoppingItem>) => void;
  onDelete: () => void;
  textSizeClass: string;
  titleSizeClass: string;
}

export const ItemCard: React.FC<ItemCardProps> = ({ item, onUpdate, onDelete, textSizeClass, titleSizeClass }) => {
  const timerRef = useRef<number | null>(null);

  // Local state for the input to handle typing commas/dots smoothly without cursor jumps
  const [displayPrice, setDisplayPrice] = useState(
    item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',')
  );

  // Sync display price if item.unitPrice changes externally (e.g., clearing the list)
  useEffect(() => {
    const formatted = item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',');
    // Parse current display price to check if it represents the same numeric value
    const currentNumeric = parseFloat(displayPrice.replace(',', '.'));
    const isSameValue = isNaN(currentNumeric) ? item.unitPrice === 0 : currentNumeric === item.unitPrice;

    if (!isSameValue) {
      setDisplayPrice(formatted);
    }
  }, [item.unitPrice]);

  const handlePriceChange = (val: string) => {
    // Only allow digits and a single comma or dot
    const cleanVal = val.replace(/[^0-9.,]/g, '');

    // Split by possible separators to ensure only one exists
    const parts = cleanVal.split(/[.,]/);
    if (parts.length > 2) return;

    setDisplayPrice(cleanVal);

    // Normalize to standard float format for storage
    const normalized = cleanVal.replace(',', '.');
    const price = parseFloat(normalized);
    onUpdate({ unitPrice: isNaN(price) ? 0 : price });
  };

  const handleLongPressStart = () => {
    timerRef.current = window.setTimeout(() => {
      if (window.confirm(`Excluir "${item.name}"?`)) {
        onDelete();
      }
    }, 800);
  };

  const handleLongPressEnd = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
  };

  const total = item.unitPrice * item.quantity;

  return (
    <div 
      className={`bg-white rounded-2xl p-4 border border-gray-100 shadow-sm transition-all duration-300 relative overflow-hidden ${!item.isAvailable ? 'opacity-50' : 'opacity-100'}`}
      onTouchStart={handleLongPressStart}
      onTouchEnd={handleLongPressEnd}
      onMouseDown={handleLongPressStart}
      onMouseUp={handleLongPressEnd}
    >
      <div className="flex flex-col gap-3">
        {/* Top Row: Name and Availability Toggle */}
        <div className="flex justify-between items-start gap-2">
          <h3 className={`font-bold flex-1 break-words ${titleSizeClass} ${!item.isAvailable ? 'line-through text-gray-400' : 'text-gray-900'}`}>
            {item.name}
          </h3>
          <button 
            onClick={() => onUpdate({ isAvailable: !item.isAvailable })}
            className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${item.isAvailable ? 'bg-blue-600' : 'bg-gray-300'}`}
          >
            <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${item.isAvailable ? 'translate-x-6' : 'translate-x-0'}`} />
          </button>
        </div>

        {/* Middle Row: Controls */}
        <div className="flex items-center justify-between gap-2">
          {/* Quantity Controls */}
          <div className="flex items-center bg-gray-50 rounded-xl p-1 border border-gray-100">
            <button 
              onClick={() => onUpdate({ quantity: Math.max(1, item.quantity - 1) })}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              −
            </button>
            <span className="w-10 text-center font-bold text-gray-700">{item.quantity}</span>
            <button 
              onClick={() => onUpdate({ quantity: item.quantity + 1 })}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              +
            </button>
          </div>

          {/* Price Input - Enhanced for comma/dot support and visual feedback */}
          <div className="flex-1 max-w-[130px]">
            <label className="text-[10px] text-gray-400 font-bold uppercase block mb-1 text-center">Preço Unitário</label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs font-medium">R$</span>
              <input
                type="text"
                inputMode="decimal"
                value={displayPrice}
                onChange={(e) => handlePriceChange(e.target.value)}
                placeholder="0,00"
                className="w-full pl-9 pr-3 py-2 bg-gray-50 border border-gray-100 rounded-xl text-right font-semibold text-gray-700 focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500 focus:bg-white outline-none transition-all shadow-sm"
              />
            </div>
          </div>
        </div>

        {/* Bottom Row: Total */}
        <div className="pt-2 border-t border-gray-50 flex justify-between items-center">
          <span className="text-gray-400 text-xs font-medium uppercase tracking-tight">Subtotal</span>
          <span className={`font-bold text-gray-900 ${textSizeClass}`}>
            R$ {total.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
      </div>

      {/* Manual Delete Button */}
      <button 
        onClick={onDelete}
        className="absolute top-0 right-0 p-1 opacity-0 hover:opacity-100 transition-opacity"
        aria-label="Excluir item"
      >
         <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-gray-300" viewBox="0 0 20 20" fill="currentColor">
          <path fillRule="evenodd" d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" clipRule="evenodd" />
        </svg>
      </button>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, TextSize, SortMode, AppSettings } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { QuickView } from './components/QuickView';
import { SettingsModal } from './components/SettingsModal';
import { PremiumModal } from './components/PremiumModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';
const MAX_FREE_ITEMS = 15;

const App: React.FC = () => {
  // --- State ---
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    isPremium: false,
    sortMode: SortMode.NameAZ
  });
  const [newItemName, setNewItemName] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showQuickView, setShowQuickView] = useState(false);
  const [showPremiumOffer, setShowPremiumOffer] = useState(false);
  const [showClearConfirm, setShowClearConfirm] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedSettings) setSettings(JSON.parse(savedSettings));
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  // --- Logic ---
  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;

    if (!settings.isPremium && items.filter(i => i.isAvailable).length >= MAX_FREE_ITEMS) {
      setShowPremiumOffer(true);
      return;
    }

    const exists = items.find(i => i.name.toLowerCase() === name.toLowerCase());
    if (exists) {
      setFeedback('Este item já está na sua lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: 1,
      unitPrice: 0,
      isAvailable: true,
      addedAt: Date.now()
    };

    setItems(prev => [newItem, ...prev]);
    setNewItemName('');
    inputRef.current?.focus();
  }, [newItemName, items, settings.isPremium]);

  const updateItem = useCallback((id: string, updates: Partial<ShoppingItem>) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
  }, []);

  const deleteItem = useCallback((id: string) => {
    setItems(prev => prev.filter(item => item.id !== id));
  }, []);

  const handleClearList = useCallback(() => {
    setItems([]);
    setShowClearConfirm(false);
  }, []);

  const sortedItems = useMemo(() => {
    const sorted = [...items];
    switch (settings.sortMode) {
      case SortMode.NameAZ:
        return sorted.sort((a, b) => a.name.localeCompare(b.name));
      case SortMode.PriceAsc:
        return sorted.sort((a, b) => (a.unitPrice * a.quantity) - (b.unitPrice * b.quantity));
      case SortMode.PriceDesc:
        return sorted.sort((a, b) => (b.unitPrice * b.quantity) - (a.unitPrice * a.quantity));
      case SortMode.Newest:
        return sorted.sort((a, b) => b.addedAt - a.addedAt);
      default:
        return sorted;
    }
  }, [items, settings.sortMode]);

  const totalValue = useMemo(() => {
    return items
      .filter(i => i.isAvailable)
      .reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0);
  }, [items]);

  const availableCount = items.filter(i => i.isAvailable).length;

  const textSizeClass = settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base';
  const titleSizeClass = settings.textSize === 'small' ? 'text-base' : settings.textSize === 'large' ? 'text-xl' : 'text-lg';

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${textSizeClass}`}>
      {/* Header */}
      <Header 
        itemCount={items.length} 
        availableCount={availableCount}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
        isPremium={settings.isPremium}
      />

      {/* Main Content */}
      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-4">
          <div className="relative">
            <input
              ref={inputRef}
              type="text"
              value={newItemName}
              onChange={(e) => setNewItemName(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && addItem()}
              placeholder="O que você precisa?"
              className="w-full pl-4 pr-12 py-3 rounded-xl border-gray-200 border bg-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
            />
            <button 
              onClick={addItem}
              className="absolute right-2 top-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center bg-blue-600 text-white rounded-lg active:scale-95 transition-transform"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
              </svg>
            </button>
          </div>
          {feedback && (
            <p className="text-amber-600 text-xs mt-2 px-1 font-medium animate-pulse">
              {feedback}
            </p>
          )}
        </div>

        <div className="flex items-center justify-between px-1">
          <span className="text-gray-500 text-xs font-semibold uppercase tracking-wider">Sua Lista</span>
          <select 
            value={settings.sortMode}
            onChange={(e) => setSettings({...settings, sortMode: e.target.value as SortMode})}
            className="text-xs bg-transparent border-none text-blue-600 font-medium focus:ring-0 cursor-pointer"
          >
            <option value={SortMode.NameAZ}>A–Z</option>
            <option value={SortMode.PriceAsc}>$ Menor</option>
            <option value={SortMode.PriceDesc}>$ Maior</option>
            <option value={SortMode.Newest}>Recentes</option>
          </select>
        </div>

        <div className="space-y-3">
          {sortedItems.length === 0 ? (
            <div className="text-center py-12 opacity-40">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 mx-auto mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
              </svg>
              <p>Sua lista está vazia</p>
            </div>
          ) : (
            sortedItems.map(item => (
              <ItemCard 
                key={item.id} 
                item={item} 
                onUpdate={(updates) => updateItem(item.id, updates)} 
                onDelete={() => deleteItem(item.id)}
                textSizeClass={textSizeClass}
                titleSizeClass={titleSizeClass}
              />
            ))
          )}
        </div>
      </main>

      <button 
        onClick={() => setShowQuickView(true)}
        className="fixed bottom-24 right-4 w-12 h-12 bg-white shadow-lg border border-gray-100 rounded-full flex items-center justify-center text-blue-600 active:scale-90 transition-transform z-20"
        aria-label="Visualização rápida"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
        </svg>
      </button>

      <footer className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-4 flex justify-between items-center shadow-[0_-4px_10px_rgba(0,0,0,0.03)] z-30">
        <span className="text-gray-500 font-medium text-sm">Total Estimado</span>
        <span className={`font-bold text-blue-600 ${settings.textSize === 'large' ? 'text-2xl' : 'text-xl'}`}>
          R$ {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
        </span>
      </footer>

      {/* Modals */}
      {showSettings && (
        <SettingsModal 
          settings={settings} 
          onUpdate={(s) => setSettings(s)} 
          onClose={() => setShowSettings(false)} 
        />
      )}
      {showQuickView && (
        <QuickView 
          items={items} 
          total={totalValue} 
          onClose={() => setShowQuickView(false)} 
          textSizeClass={textSizeClass}
        />
      )}
      {showPremiumOffer && (
        <PremiumModal 
          onUpgrade={() => {
            setSettings({ ...settings, isPremium: true });
            setShowPremiumOffer(false);
          }} 
          onClose={() => setShowPremiumOffer(false)} 
        />
      )}

      {/* Clear List Confirmation Modal */}
      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-[2rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </div>
            <h2 className="text-xl font-bold text-gray-900 text-center mb-2">Limpar lista?</h2>
            <p className="text-gray-500 text-center text-sm mb-8 leading-relaxed">Isso removerá permanentemente todos os itens da sua lista de compras.</p>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => setShowClearConfirm(false)}
                className="py-4 bg-gray-100 text-gray-700 font-bold rounded-xl active:bg-gray-200 transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleClearList}
                className="py-4 bg-[#dc2626] text-white font-bold rounded-xl active:scale-95 transition-transform"
              >
                Sim, limpar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

