export type TextSize = 'small' | 'medium' | 'large';

export enum SortMode {
  NameAZ = 'NameAZ',
  PriceAsc = 'PriceAsc',
  PriceDesc = 'PriceDesc',
  Newest = 'Newest'
}

export interface ShoppingItem {
  id: string;
  name: string;
  quantity: number;
  unitPrice: number;
  isAvailable: boolean;
  addedAt: number;
}

export interface AppSettings {
  textSize: TextSize;
  sortMode: SortMode;
  isBudgetModeActive: boolean;
  budgetLimit: number;
}

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, TextSize, SortMode, AppSettings } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { QuickView } from './components/QuickView';
import { SettingsModal } from './components/SettingsModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

const App: React.FC = () => {
  // --- State ---
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
  });
  const [newItemName, setNewItemName] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showQuickView, setShowQuickView] = useState(false);
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  // Undo Logic State
  const [lastDeletedItem, setLastDeletedItem] = useState<ShoppingItem | null>(null);
  const undoTimeoutRef = useRef<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      setSettings({
        ...settings,
        ...parsed
      });
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  // --- Logic ---
  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;

    const exists = items.find(i => i.name.toLowerCase() === name.toLowerCase());
    if (exists) {
      setFeedback('Este item já está na sua lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: 1,
      unitPrice: 0,
      isAvailable: true,
      addedAt: Date.now()
    };

    setItems(prev => [newItem, ...prev]);
    setNewItemName('');
    inputRef.current?.focus();
  }, [newItemName, items]);

  const updateItem = useCallback((id: string, updates: Partial<ShoppingItem>) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
  }, []);

  const deleteItem = useCallback((id: string) => {
    const itemToDelete = items.find(i => i.id === id);
    if (itemToDelete) {
      // Store for undo
      setLastDeletedItem(itemToDelete);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
      undoTimeoutRef.current = window.setTimeout(() => {
        setLastDeletedItem(null);
      }, 5000);

      setItems(prev => prev.filter(item => item.id !== id));
    }
  }, [items]);

  const undoDelete = useCallback(() => {
    if (lastDeletedItem) {
      setItems(prev => [lastDeletedItem, ...prev]);
      setLastDeletedItem(null);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    }
  }, [lastDeletedItem]);

  const handleClearList = useCallback(() => {
    setItems([]);
    setShowClearConfirm(false);
  }, []);

  const filteredAndSortedItems = useMemo(() => {
    let filtered = items.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    switch (settings.sortMode) {
      case SortMode.NameAZ:
        filtered.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case SortMode.PriceAsc:
        filtered.sort((a, b) => (a.unitPrice * a.quantity) - (b.unitPrice * b.quantity));
        break;
      case SortMode.PriceDesc:
        filtered.sort((a, b) => (b.unitPrice * b.quantity) - (a.unitPrice * a.quantity));
        break;
      case SortMode.Newest:
        filtered.sort((a, b) => b.addedAt - a.addedAt);
        break;
    }
    return filtered;
  }, [items, searchTerm, settings.sortMode]);

  const totalValue = useMemo(() => {
    return items
      .filter(i => i.isAvailable)
      .reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0);
  }, [items]);

  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  const availableCount = items.filter(i => i.isAvailable).length;

  const textSizeClass = settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base';
  const titleSizeClass = settings.textSize === 'small' ? 'text-base' : settings.textSize === 'large' ? 'text-xl' : 'text-lg';

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${textSizeClass}`}>
      {/* Header */}
      <Header 
        itemCount={items.length} 
        availableCount={availableCount}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
      />

      {/* Main Content */}
      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {/* Input Section */}
        <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
          <div className="relative">
            <input
              ref={inputRef}
              type="text"
              value={newItemName}
              onChange={(e) => setNewItemName(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && addItem()}
              placeholder="O que você precisa?"
              className="w-full pl-4 pr-12 py-3 rounded-xl border-gray-200 border bg-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
            />
            <button 
              onClick={addItem}
              className="absolute right-2 top-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center bg-blue-600 text-white rounded-lg active:scale-95 transition-transform"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
              </svg>
            </button>
          </div>
          {feedback && (
            <p className="text-amber-600 text-xs mt-2 px-1 font-medium animate-pulse">
              {feedback}
            </p>
          )}
        </div>

        {/* Search Bar - Discreet */}
        <div className="relative px-1">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar item..."
            className="w-full bg-gray-100/50 border-none rounded-xl py-2 pl-10 pr-4 text-xs focus:ring-1 focus:ring-gray-200 transition-all outline-none"
          />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          {searchTerm && (
            <button 
              onClick={() => setSearchTerm('')}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          )}
        </div>

        <div className="flex items-center justify-between px-1">
          <span className="text-gray-500 text-[10px] font-bold uppercase tracking-widest">
            {searchTerm ? `Resultados: ${filteredAndSortedItems.length}` : 'Sua Lista'}
          </span>
          <select 
            value={settings.sortMode}
            onChange={(e) => setSettings({...settings, sortMode: e.target.value as SortMode})}
            className="text-[10px] bg-transparent border-none text-blue-600 font-bold uppercase focus:ring-0 cursor-pointer tracking-wider"
          >
            <option value={SortMode.NameAZ}>A–Z</option>
            <option value={SortMode.PriceAsc}>$ Menor</option>
            <option value={SortMode.PriceDesc}>$ Maior</option>
            <option value={SortMode.Newest}>Recentes</option>
          </select>
        </div>

        <div className="space-y-3">
          {filteredAndSortedItems.length === 0 ? (
            <div className="text-center py-12 opacity-40">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
              </svg>
              <p className="text-xs uppercase font-bold tracking-widest">Nenhum item encontrado</p>
            </div>
          ) : (
            filteredAndSortedItems.map(item => (
              <ItemCard 
                key={item.id} 
                item={item} 
                onUpdate={(updates) => updateItem(item.id, updates)} 
                onDelete={() => deleteItem(item.id)}
                textSizeClass={textSizeClass}
                titleSizeClass={titleSizeClass}
              />
            ))
          )}
        </div>
      </main>

      {/* Undo Toast */}
      {lastDeletedItem && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-sm z-[80] animate-in slide-in-from-bottom duration-300">
          <div className="bg-gray-900 text-white px-4 py-3 rounded-2xl flex items-center justify-between shadow-xl">
            <span className="text-sm font-medium">Item removido: <b>{lastDeletedItem.name}</b></span>
            <button 
              onClick={undoDelete}
              className="text-blue-400 font-bold text-sm uppercase tracking-wider active:scale-90 transition-transform"
            >
              Desfazer
            </button>
          </div>
        </div>
      )}

      {/* Quick View FAB */}
      <button 
        onClick={() => setShowQuickView(true)}
        className="fixed bottom-24 right-4 w-12 h-12 bg-white shadow-lg border border-gray-100 rounded-full flex items-center justify-center text-blue-600 active:scale-90 transition-transform z-20"
        aria-label="Visualização rápida"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
        </svg>
      </button>

      {/* Footer Total */}
      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-4 flex flex-col items-center shadow-[0_-4px_10px_rgba(0,0,0,0.03)] z-30 transition-colors ${budgetExceeded ? 'border-red-500 bg-red-50' : ''}`}>
        <div className="w-full flex justify-between items-center">
          <div className="flex flex-col">
            <span className={`font-medium text-xs uppercase tracking-widest ${budgetExceeded ? 'text-red-600' : 'text-gray-500'}`}>Total Estimado</span>
            {settings.isBudgetModeActive && (
              <span className="text-[10px] text-gray-400 font-bold uppercase">Orçamento: R$ {settings.budgetLimit.toFixed(2)}</span>
            )}
          </div>
          <span className={`font-bold transition-colors ${budgetExceeded ? 'text-red-600' : 'text-blue-600'} ${settings.textSize === 'large' ? 'text-2xl' : 'text-xl'}`}>
            R$ {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
        {budgetExceeded && (
          <p className="text-[10px] text-red-600 font-bold uppercase mt-1 tracking-tighter animate-pulse">
            Você ultrapassou seu orçamento
          </p>
        )}
      </footer>

      {/* Modals */}
      {showSettings && (
        <SettingsModal 
          settings={settings} 
          onUpdate={(s) => setSettings(s)} 
          onClose={() => setShowSettings(false)} 
        />
      )}
      {showQuickView && (
        <QuickView 
          items={items} 
          total={totalValue} 
          onClose={() => setShowQuickView(false)} 
          textSizeClass={textSizeClass}
        />
      )}

      {/* Clear List Confirmation Modal */}
      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-[2rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </div>
            <h2 className="text-xl font-bold text-gray-900 text-center mb-2">Limpar lista?</h2>
            <p className="text-gray-500 text-center text-sm mb-8 leading-relaxed">Isso removerá permanentemente todos os itens da sua lista de compras.</p>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => setShowClearConfirm(false)}
                className="py-4 bg-gray-100 text-gray-700 font-bold rounded-xl active:bg-gray-200 transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleClearList}
                className="py-4 bg-[#dc2626] text-white font-bold rounded-xl active:scale-95 transition-transform"
              >
                Sim, limpar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

