import React, { useState, useEffect } from 'react';
import { AppSettings, TextSize } from '../types';

interface SettingsModalProps {
  settings: AppSettings;
  onUpdate: (s: AppSettings) => void;
  onClose: () => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ settings, onUpdate, onClose }) => {
  const [displayBudget, setDisplayBudget] = useState(
    settings.budgetLimit === 0 ? '' : settings.budgetLimit.toString().replace('.', ',')
  );

  useEffect(() => {
    const formatted = settings.budgetLimit === 0 ? '' : settings.budgetLimit.toString().replace('.', ',');
    const currentNumeric = parseFloat(displayBudget.replace(',', '.'));
    const isSameValue = isNaN(currentNumeric) ? settings.budgetLimit === 0 : currentNumeric === settings.budgetLimit;

    if (!isSameValue) {
      setDisplayBudget(formatted);
    }
  }, [settings.budgetLimit]);

  const sizes: { value: TextSize; label: string; desc: string }[] = [
    { value: 'small', label: 'Pequeno', desc: 'Minimalista' },
    { value: 'medium', label: 'Médio', desc: 'Padrão' },
    { value: 'large', label: 'Grande', desc: 'Acessível' },
  ];

  const handleBudgetChange = (val: string) => {
    const cleanVal = val.replace(/[^0-9.,]/g, '');
    const parts = cleanVal.split(/[.,]/);
    if (parts.length > 2) return;

    setDisplayBudget(cleanVal);
    const normalized = cleanVal.replace(',', '.');
    const budget = parseFloat(normalized);
    onUpdate({ ...settings, budgetLimit: isNaN(budget) ? 0 : budget });
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-end sm:items-center justify-center p-0 sm:p-4 animate-in fade-in duration-200">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-bottom duration-300">
        <div className="w-12 h-1.5 bg-gray-200 rounded-full mx-auto mb-6 sm:hidden" onClick={onClose} />
        <h2 className="text-xl font-bold text-gray-900 mb-6">Configurações</h2>

        <div className="space-y-8 overflow-y-auto max-h-[70vh] pb-4">
          {/* Text Size Section */}
          <div>
            <label className="text-xs font-bold text-gray-400 uppercase tracking-widest block mb-4">Tamanho do Texto</label>
            <div className="grid grid-cols-3 gap-3">
              {sizes.map(size => (
                <button
                  key={size.value}
                  onClick={() => onUpdate({ ...settings, textSize: size.value })}
                  className={`flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all ${
                    settings.textSize === size.value 
                    ? 'border-blue-600 bg-blue-50 text-blue-700' 
                    : 'border-gray-100 bg-gray-50 text-gray-400'
                  }`}
                >
                  <span className={`font-bold ${size.value === 'large' ? 'text-lg' : size.value === 'small' ? 'text-xs' : 'text-sm'}`}>Aa</span>
                  <span className="text-[10px] mt-1 font-semibold uppercase">{size.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Budget and Haptic Section */}
          <div className="space-y-4">
            {/* Budget Mode Toggle */}
            <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
              <div className="flex justify-between items-center mb-4">
                <div>
                  <label className="text-xs font-bold text-gray-900 uppercase tracking-tight block">Modo Orçamento</label>
                  <p className="text-[10px] text-gray-400 font-medium">Controle seus gastos totais</p>
                </div>
                <button 
                  onClick={() => onUpdate({ ...settings, isBudgetModeActive: !settings.isBudgetModeActive })}
                  className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${settings.isBudgetModeActive ? 'bg-blue-600' : 'bg-gray-300'}`}
                >
                  <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${settings.isBudgetModeActive ? 'translate-x-6' : 'translate-x-0'}`} />
                </button>
              </div>

              {settings.isBudgetModeActive && (
                <div className="mt-4 animate-in slide-in-from-top duration-200">
                  <label className="text-[10px] text-gray-400 font-bold uppercase block mb-1">Valor Máximo</label>
                  <div className="relative">
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 text-sm font-medium">R$</span>
                    <input
                      type="text"
                      inputMode="decimal"
                      value={displayBudget}
                      onChange={(e) => handleBudgetChange(e.target.value)}
                      placeholder="0,00"
                      className="w-full pl-11 pr-4 py-3 bg-white border border-gray-200 rounded-xl text-left font-bold text-gray-700 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                    />
                  </div>
                </div>
              )}
            </div>

            {/* Haptic Feedback Toggle */}
            <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100 flex justify-between items-center">
              <div>
                <label className="text-xs font-bold text-gray-900 uppercase tracking-tight block">Feedback Tátil</label>
                <p className="text-[10px] text-gray-400 font-medium">Vibração leve ao interagir</p>
              </div>
              <button 
                onClick={() => onUpdate({ ...settings, isHapticEnabled: !settings.isHapticEnabled })}
                className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${settings.isHapticEnabled ? 'bg-blue-600' : 'bg-gray-300'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${settings.isHapticEnabled ? 'translate-x-6' : 'translate-x-0'}`} />
              </button>
            </div>
          </div>

          <div className="pt-2 border-t border-gray-100">
             <button 
              onClick={onClose}
              className="w-full py-4 bg-gray-900 text-white font-bold rounded-2xl active:scale-95 transition-transform shadow-lg shadow-gray-200"
            >
              Confirmar
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

