          Voltar para Lista
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, TextSize, SortMode, AppSettings } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { QuickView } from './components/QuickView';
import { SettingsModal } from './components/SettingsModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

const App: React.FC = () => {
  // --- State ---
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    isHapticEnabled: true,
  });
  const [newItemName, setNewItemName] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showQuickView, setShowQuickView] = useState(false);
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  // Undo Logic State
  const [lastDeletedItem, setLastDeletedItem] = useState<ShoppingItem | null>(null);
  const undoTimeoutRef = useRef<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      setSettings(prev => ({
        ...prev,
        ...parsed
      }));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  // --- Haptic Feedback Helper ---
  const triggerVibration = useCallback(() => {
    if (settings.isHapticEnabled && 'vibrate' in navigator) {
      navigator.vibrate(30); // Aumentado para 30ms para ser mais perceptível
    }
  }, [settings.isHapticEnabled]);

  // --- Logic ---
  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;

    const exists = items.find(i => i.name.toLowerCase() === name.toLowerCase());
    if (exists) {
      setFeedback('Este item já está na sua lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: 1,
      unitPrice: 0,
      isAvailable: true,
      addedAt: Date.now()
    };

    triggerVibration(); // Gatilho: Adicionar item
    setItems(prev => [newItem, ...prev]);
    setNewItemName('');
    inputRef.current?.focus();
  }, [newItemName, items, triggerVibration]);

  const updateItem = useCallback((id: string, updates: Partial<ShoppingItem>) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
  }, []);

  const deleteItem = useCallback((id: string) => {
    const itemToDelete = items.find(i => i.id === id);
    if (itemToDelete) {
      triggerVibration(); // Gatilho: Excluir item
      // Store for undo
      setLastDeletedItem(itemToDelete);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
      undoTimeoutRef.current = window.setTimeout(() => {
        setLastDeletedItem(null);
      }, 5000);

      setItems(prev => prev.filter(item => item.id !== id));
    }
  }, [items, triggerVibration]);

  const undoDelete = useCallback(() => {
    if (lastDeletedItem) {
      triggerVibration(); // Gatilho: Desfazer exclusão
      setItems(prev => [lastDeletedItem, ...prev]);
      setLastDeletedItem(null);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    }
  }, [lastDeletedItem, triggerVibration]);

  const handleClearList = useCallback(() => {
    triggerVibration();
    setItems([]);
    setShowClearConfirm(false);
  }, [triggerVibration]);

  const sections = useMemo(() => {
    let filtered = items.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    switch (settings.sortMode) {
      case SortMode.NameAZ:
        filtered.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case SortMode.PriceAsc:
        filtered.sort((a, b) => (a.unitPrice * a.quantity) - (b.unitPrice * b.quantity));
        break;
      case SortMode.PriceDesc:
        filtered.sort((a, b) => (b.unitPrice * b.quantity) - (a.unitPrice * a.quantity));
        break;
      case SortMode.Newest:
        filtered.sort((a, b) => b.addedAt - a.addedAt);
        break;
    }

    return {
      available: filtered.filter(i => i.isAvailable),
      unavailable: filtered.filter(i => !i.isAvailable)
    };
  }, [items, searchTerm, settings.sortMode]);

  const totalValue = useMemo(() => {
    return items
      .filter(i => i.isAvailable)
      .reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0);
  }, [items]);

  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  const availableCount = items.filter(i => i.isAvailable).length;

  const textSizeClass = settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base';
  const titleSizeClass = settings.textSize === 'small' ? 'text-base' : settings.textSize === 'large' ? 'text-xl' : 'text-lg';

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${textSizeClass}`}>
      {/* Header */}
      <Header 
        itemCount={items.length} 
        availableCount={availableCount}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
      />

      {/* Main Content */}
      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {/* Input Section */}
        <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
          <div className="relative">
            <input
              ref={inputRef}
              type="text"
              value={newItemName}
              onChange={(e) => setNewItemName(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && addItem()}
              placeholder="O que você precisa?"
              className="w-full pl-4 pr-12 py-3 rounded-xl border-gray-200 border bg-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
            />
            <button 
              onClick={addItem}
              className="absolute right-2 top-1/2 -translate-y-1/2 w-10 h-10 flex items-center justify-center bg-blue-600 text-white rounded-lg active:scale-95 transition-transform"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
              </svg>
            </button>
          </div>
          {feedback && (
            <p className="text-amber-600 text-xs mt-2 px-1 font-medium animate-pulse">
              {feedback}
            </p>
          )}
        </div>

        {/* Search Bar - Discreet */}
        <div className="relative px-1">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar item..."
            className="w-full bg-gray-100/50 border-none rounded-xl py-2 pl-10 pr-4 text-xs focus:ring-1 focus:ring-gray-200 transition-all outline-none"
          />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          {searchTerm && (
            <button 
              onClick={() => setSearchTerm('')}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          )}
        </div>

        <div className="flex items-center justify-between px-1">
          <span className="text-gray-500 text-[10px] font-bold uppercase tracking-widest">
            {searchTerm ? `Resultados: ${sections.available.length + sections.unavailable.length}` : 'Sua Lista'}
          </span>
          <select 
            value={settings.sortMode}
            onChange={(e) => setSettings({...settings, sortMode: e.target.value as SortMode})}
            className="text-[10px] bg-transparent border-none text-blue-600 font-bold uppercase focus:ring-0 cursor-pointer tracking-wider"
          >
            <option value={SortMode.NameAZ}>A–Z</option>
            <option value={SortMode.PriceAsc}>$ Menor</option>
            <option value={SortMode.PriceDesc}>$ Maior</option>
            <option value={SortMode.Newest}>Recentes</option>
          </select>
        </div>

        <div className="space-y-6">
          {sections.available.length === 0 && sections.unavailable.length === 0 ? (
            <div className="text-center py-12 opacity-40">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
              </svg>
              <p className="text-xs uppercase font-bold tracking-widest">Nenhum item encontrado</p>
            </div>
          ) : (
            <>
              {/* Available Section */}
              {sections.available.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Itens disponíveis</span>
                  </div>
                  {sections.available.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                    />
                  ))}
                </div>
              )}

              {/* Unavailable Section */}
              {sections.unavailable.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-gray-400 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Itens indisponíveis</span>
                  </div>
                  {sections.unavailable.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                    />
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </main>

      {/* Undo Toast */}
      {lastDeletedItem && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-sm z-[80] animate-in slide-in-from-bottom duration-300">
          <div className="bg-gray-900 text-white px-4 py-3 rounded-2xl flex items-center justify-between shadow-xl">
            <span className="text-sm font-medium">Item removido: <b>{lastDeletedItem.name}</b></span>
            <button 
              onClick={undoDelete}
              className="text-blue-400 font-bold text-sm uppercase tracking-wider active:scale-90 transition-transform"
            >
              Desfazer
            </button>
          </div>
        </div>
      )}

      {/* Quick View FAB */}
      <button 
        onClick={() => setShowQuickView(true)}
        className="fixed bottom-24 right-4 w-12 h-12 bg-white shadow-lg border border-gray-100 rounded-full flex items-center justify-center text-blue-600 active:scale-90 transition-transform z-20"
        aria-label="Visualização rápida"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
        </svg>
      </button>

      {/* Footer Total */}
      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-4 flex flex-col items-center shadow-[0_-4px_10px_rgba(0,0,0,0.03)] z-30 transition-colors ${budgetExceeded ? 'border-red-500 bg-red-50' : ''}`}>
        <div className="w-full flex justify-between items-center">
          <div className="flex flex-col">
            <span className={`font-medium text-xs uppercase tracking-widest ${budgetExceeded ? 'text-red-600' : 'text-gray-500'}`}>Total Estimado</span>
            {settings.isBudgetModeActive && (
              <span className="text-[10px] text-gray-400 font-bold uppercase">Orçamento: R$ {settings.budgetLimit.toFixed(2)}</span>
            )}
          </div>
          <span className={`font-bold transition-colors ${budgetExceeded ? 'text-red-600' : 'text-blue-600'} ${settings.textSize === 'large' ? 'text-2xl' : 'text-xl'}`}>
            R$ {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
        {budgetExceeded && (
          <p className="text-[10px] text-red-600 font-bold uppercase mt-1 tracking-tighter animate-pulse">
            Você ultrapassou seu orçamento
          </p>
        )}
      </footer>

      {/* Modals */}
      {showSettings && (
        <SettingsModal 
          settings={settings} 
          onUpdate={(s) => setSettings(s)} 
          onClose={() => setShowSettings(false)} 
        />
      )}
      {showQuickView && (
        <QuickView 
          items={items} 
          total={totalValue} 
          onClose={() => setShowQuickView(false)} 
          textSizeClass={textSizeClass}
        />
      )}

      {/* Clear List Confirmation Modal */}
      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-sm rounded-[2rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </div>
            <h2 className="text-xl font-bold text-gray-900 text-center mb-2">Limpar lista?</h2>
            <p className="text-gray-500 text-center text-sm mb-8 leading-relaxed">Isso removerá permanentemente todos os itens da sua lista de compras.</p>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => setShowClearConfirm(false)}
                className="py-4 bg-gray-100 text-gray-700 font-bold rounded-xl active:bg-gray-200 transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleClearList}
                className="py-4 bg-[#dc2626] text-white font-bold rounded-xl active:scale-95 transition-transform"
              >
                Sim, limpar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { ShoppingItem } from '../types';

interface ItemCardProps {
  item: ShoppingItem;
  onUpdate: (updates: Partial<ShoppingItem>) => void;
  onDelete: () => void;
  textSizeClass: string;
  titleSizeClass: string;
  isHapticEnabled: boolean;
}

export const ItemCard: React.FC<ItemCardProps> = ({ item, onUpdate, onDelete, textSizeClass, titleSizeClass, isHapticEnabled }) => {
  const timerRef = useRef<number | null>(null);

  // Local state for the input to handle typing commas/dots smoothly without cursor jumps
  const [displayPrice, setDisplayPrice] = useState(
    item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',')
  );

  // Sync display price if item.unitPrice changes externally (e.g., clearing the list)
  useEffect(() => {
    const formatted = item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',');
    // Parse current display price to check if it represents the same numeric value
    const currentNumeric = parseFloat(displayPrice.replace(',', '.'));
    const isSameValue = isNaN(currentNumeric) ? item.unitPrice === 0 : currentNumeric === item.unitPrice;

    if (!isSameValue) {
      setDisplayPrice(formatted);
    }
  }, [item.unitPrice]);

  const triggerVibration = () => {
    if (isHapticEnabled && 'vibrate' in navigator) {
      navigator.vibrate(30); // Aumentado para 30ms para ser mais perceptível
    }
  };

  const handlePriceChange = (val: string) => {
    // Only allow digits and a single comma or dot
    const cleanVal = val.replace(/[^0-9.,]/g, '');

    // Split by possible separators to ensure only one exists
    const parts = cleanVal.split(/[.,]/);
    if (parts.length > 2) return;

    setDisplayPrice(cleanVal);

    // Normalize to standard float format for storage
    const normalized = cleanVal.replace(',', '.');
    const price = parseFloat(normalized);
    onUpdate({ unitPrice: isNaN(price) ? 0 : price });
  };

  const handleLongPressStart = () => {
    timerRef.current = window.setTimeout(() => {
      // Still support long press for redundancy if desired, or relying purely on the new icon
    }, 800);
  };

  const handleLongPressEnd = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
  };

  const total = item.unitPrice * item.quantity;

  return (
    <div 
      className={`bg-white rounded-2xl p-4 border border-gray-100 shadow-sm transition-all duration-300 relative overflow-hidden ${!item.isAvailable ? 'opacity-50' : 'opacity-100'}`}
      onTouchStart={handleLongPressStart}
      onTouchEnd={handleLongPressEnd}
      onMouseDown={handleLongPressStart}
      onMouseUp={handleLongPressEnd}
    >
      <div className="flex flex-col gap-3">
        {/* Top Row: Name, Delete Icon and Availability Toggle */}
        <div className="flex justify-between items-start gap-2">
          <h3 className={`font-bold flex-1 break-words ${titleSizeClass} ${!item.isAvailable ? 'line-through text-gray-400' : 'text-gray-900'}`}>
            {item.name}
          </h3>
          <div className="flex items-center gap-3 shrink-0">
            {/* New Discreet Remove Icon */}
            <button 
              onClick={(e) => {
                e.stopPropagation();
                onDelete();
              }}
              className="p-1.5 text-gray-300 hover:text-red-500 active:text-red-600 transition-colors"
              aria-label="Excluir item"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
            <button 
              onClick={() => {
                triggerVibration(); // Gatilho: Marcar disponibilidade
                onUpdate({ isAvailable: !item.isAvailable });
              }}
              className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${item.isAvailable ? 'bg-blue-600' : 'bg-gray-300'}`}
            >
              <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${item.isAvailable ? 'translate-x-6' : 'translate-x-0'}`} />
            </button>
          </div>
        </div>

        {/* Middle Row: Controls */}
        <div className="flex items-center justify-between gap-2">
          {/* Quantity Controls */}
          <div className="flex items-center bg-gray-50 rounded-xl p-1 border border-gray-100">
            <button 
              onClick={() => {
                triggerVibration();
                onUpdate({ quantity: Math.max(1, item.quantity - 1) });
              }}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              −
            </button>
            <span className="w-10 text-center font-bold text-gray-700">{item.quantity}</span>
            <button 
              onClick={() => {
                triggerVibration();
                onUpdate({ quantity: item.quantity + 1 });
              }}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              +
            </button>
          </div>

          {/* Price Input */}
          <div className="flex-1 max-w-[130px]">
            <label className="text-[10px] text-gray-400 font-bold uppercase block mb-1 text-center">Preço Unitário</label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs font-medium">R$</span>
              <input
                type="text"
                inputMode="decimal"
                value={displayPrice}
                onChange={(e) => handlePriceChange(e.target.value)}
                placeholder="0,00"
                className="w-full pl-9 pr-3 py-2 bg-gray-50 border border-gray-100 rounded-xl text-right font-semibold text-gray-700 focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500 focus:bg-white outline-none transition-all shadow-sm"
              />
            </div>
          </div>
        </div>

        {/* Bottom Row: Total */}
        <div className="pt-2 border-t border-gray-50 flex justify-between items-center">
          <span className="text-gray-400 text-xs font-medium uppercase tracking-tight">Subtotal</span>
          <span className={`font-bold text-gray-900 ${textSizeClass}`}>
            R$ {total.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { AppSettings, TextSize } from '../types';

interface SettingsModalProps {
  settings: AppSettings;
  onUpdate: (s: AppSettings) => void;
  onClose: () => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ settings, onUpdate, onClose }) => {
  const [displayBudget, setDisplayBudget] = useState(
    settings.budgetLimit === 0 ? '' : settings.budgetLimit.toString().replace('.', ',')
  );

  useEffect(() => {
    const formatted = settings.budgetLimit === 0 ? '' : settings.budgetLimit.toString().replace('.', ',');
    const currentNumeric = parseFloat(displayBudget.replace(',', '.'));
    const isSameValue = isNaN(currentNumeric) ? settings.budgetLimit === 0 : currentNumeric === settings.budgetLimit;

    if (!isSameValue) {
      setDisplayBudget(formatted);
    }
  }, [settings.budgetLimit]);

  const sizes: { value: TextSize; label: string; desc: string }[] = [
    { value: 'small', label: 'Pequeno', desc: 'Minimalista' },
    { value: 'medium', label: 'Médio', desc: 'Padrão' },
    { value: 'large', label: 'Grande', desc: 'Acessível' },
  ];

  const handleBudgetChange = (val: string) => {
    const cleanVal = val.replace(/[^0-9.,]/g, '');
    const parts = cleanVal.split(/[.,]/);
    if (parts.length > 2) return;

    setDisplayBudget(cleanVal);
    const normalized = cleanVal.replace(',', '.');
    const budget = parseFloat(normalized);
    onUpdate({ ...settings, budgetLimit: isNaN(budget) ? 0 : budget });
  };

  const handleHapticToggle = () => {
    const nextValue = !settings.isHapticEnabled;
    // Gatilho: Teste de vibração ao ativar
    if (nextValue && 'vibrate' in navigator) {
      navigator.vibrate(30);
    }
    onUpdate({ ...settings, isHapticEnabled: nextValue });
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-end sm:items-center justify-center p-0 sm:p-4 animate-in fade-in duration-200">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-bottom duration-300">
        <div className="w-12 h-1.5 bg-gray-200 rounded-full mx-auto mb-6 sm:hidden" onClick={onClose} />
        <h2 className="text-xl font-bold text-gray-900 mb-6">Configurações</h2>

        <div className="space-y-8 overflow-y-auto max-h-[70vh] pb-4">
          {/* Text Size Section */}
          <div>
            <label className="text-xs font-bold text-gray-400 uppercase tracking-widest block mb-4">Tamanho do Texto</label>
            <div className="grid grid-cols-3 gap-3">
              {sizes.map(size => (
                <button
                  key={size.value}
                  onClick={() => onUpdate({ ...settings, textSize: size.value })}
                  className={`flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all ${
                    settings.textSize === size.value 
                    ? 'border-blue-600 bg-blue-50 text-blue-700' 
                    : 'border-gray-100 bg-gray-50 text-gray-400'
                  }`}
                >
                  <span className={`font-bold ${size.value === 'large' ? 'text-lg' : size.value === 'small' ? 'text-xs' : 'text-sm'}`}>Aa</span>
                  <span className="text-[10px] mt-1 font-semibold uppercase">{size.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Budget and Haptic Section */}
          <div className="space-y-4">
            {/* Budget Mode Toggle */}
            <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
              <div className="flex justify-between items-center mb-4">
                <div>
                  <label className="text-xs font-bold text-gray-900 uppercase tracking-tight block">Modo Orçamento</label>
                  <p className="text-[10px] text-gray-400 font-medium">Controle seus gastos totais</p>
                </div>
                <button 
                  onClick={() => onUpdate({ ...settings, isBudgetModeActive: !settings.isBudgetModeActive })}
                  className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${settings.isBudgetModeActive ? 'bg-blue-600' : 'bg-gray-300'}`}
                >
                  <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${settings.isBudgetModeActive ? 'translate-x-6' : 'translate-x-0'}`} />
                </button>
              </div>

              {settings.isBudgetModeActive && (
                <div className="mt-4 animate-in slide-in-from-top duration-200">
                  <label className="text-[10px] text-gray-400 font-bold uppercase block mb-1">Valor Máximo</label>
                  <div className="relative">
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 text-sm font-medium">R$</span>
                    <input
                      type="text"
                      inputMode="decimal"
                      value={displayBudget}
                      onChange={(e) => handleBudgetChange(e.target.value)}
                      placeholder="0,00"
                      className="w-full pl-11 pr-4 py-3 bg-white border border-gray-200 rounded-xl text-left font-bold text-gray-700 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                    />
                  </div>
                </div>
              )}
            </div>

            {/* Haptic Feedback Toggle */}
            <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100 flex justify-between items-center">
              <div>
                <label className="text-xs font-bold text-gray-900 uppercase tracking-tight block">Feedback Tátil</label>
                <p className="text-[10px] text-gray-400 font-medium">Vibração leve ao interagir</p>
              </div>
              <button 
                onClick={handleHapticToggle}
                className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${settings.isHapticEnabled ? 'bg-blue-600' : 'bg-gray-300'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${settings.isHapticEnabled ? 'translate-x-6' : 'translate-x-0'}`} />
              </button>
            </div>
          </div>

          <div className="pt-2 border-t border-gray-100">
             <button 
              onClick={onClose}
              className="w-full py-4 bg-gray-900 text-white font-bold rounded-2xl active:scale-95 transition-transform shadow-lg shadow-gray-200"
            >
              Confirmar
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, TextSize, SortMode, AppSettings } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { QuickView } from './components/QuickView';
import { SettingsModal } from './components/SettingsModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

const App: React.FC = () => {
  // --- State ---
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    isHapticEnabled: true,
  });
  const [newItemName, setNewItemName] = useState('');
  const [newItemQty, setNewItemQty] = useState<string>('1');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showQuickView, setShowQuickView] = useState(false);
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  // Undo Logic State
  const [lastDeletedItem, setLastDeletedItem] = useState<ShoppingItem | null>(null);
  const undoTimeoutRef = useRef<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      setSettings(prev => ({
        ...prev,
        ...parsed
      }));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  // --- Haptic Feedback Helper ---
  const triggerVibration = useCallback(() => {
    if (settings.isHapticEnabled && 'vibrate' in navigator) {
      navigator.vibrate(30); 
    }
  }, [settings.isHapticEnabled]);

  // --- Logic ---
  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;

    const exists = items.find(i => i.name.toLowerCase() === name.toLowerCase());
    if (exists) {
      setFeedback('Este item já está na sua lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const qty = parseInt(newItemQty) || 1;

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: qty,
      unitPrice: 0,
      isAvailable: true,
      addedAt: Date.now()
    };

    triggerVibration(); 
    setItems(prev => [newItem, ...prev]);
    setNewItemName('');
    setNewItemQty('1');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, items, triggerVibration]);

  const updateItem = useCallback((id: string, updates: Partial<ShoppingItem>) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
  }, []);

  const deleteItem = useCallback((id: string) => {
    const itemToDelete = items.find(i => i.id === id);
    if (itemToDelete) {
      triggerVibration(); 
      setLastDeletedItem(itemToDelete);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
      undoTimeoutRef.current = window.setTimeout(() => {
        setLastDeletedItem(null);
      }, 5000);

      setItems(prev => prev.filter(item => item.id !== id));
    }
  }, [items, triggerVibration]);

  const undoDelete = useCallback(() => {
    if (lastDeletedItem) {
      triggerVibration(); 
      setItems(prev => [lastDeletedItem, ...prev]);
      setLastDeletedItem(null);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    }
  }, [lastDeletedItem, triggerVibration]);

  const handleClearList = useCallback(() => {
    triggerVibration();
    setItems([]);
    setShowClearConfirm(false);
  }, [triggerVibration]);

  const sections = useMemo(() => {
    let filtered = items.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    switch (settings.sortMode) {
      case SortMode.NameAZ:
        filtered.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case SortMode.PriceAsc:
        filtered.sort((a, b) => (a.unitPrice * a.quantity) - (b.unitPrice * b.quantity));
        break;
      case SortMode.PriceDesc:
        filtered.sort((a, b) => (b.unitPrice * b.quantity) - (a.unitPrice * a.quantity));
        break;
      case SortMode.Newest:
        filtered.sort((a, b) => b.addedAt - a.addedAt);
        break;
    }

    return {
      available: filtered.filter(i => i.isAvailable),
      unavailable: filtered.filter(i => !i.isAvailable)
    };
  }, [items, searchTerm, settings.sortMode]);

  const totalValue = useMemo(() => {
    return items
      .filter(i => i.isAvailable)
      .reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0);
  }, [items]);

  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  const availableCount = items.filter(i => i.isAvailable).length;

  const textSizeClass = settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base';
  const titleSizeClass = settings.textSize === 'small' ? 'text-base' : settings.textSize === 'large' ? 'text-xl' : 'text-lg';

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${textSizeClass}`}>
      {/* Header */}
      <Header 
        itemCount={items.length} 
        availableCount={availableCount}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
      />

      {/* Main Content */}
      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {/* Input Section - Refined to include QTD input */}
        <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
          <div className="flex gap-2">
            <div className="flex-1 relative">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que você precisa?"
                className="w-full px-4 py-3 rounded-xl border-gray-200 border bg-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
              />
            </div>

            <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner">
              <input
                type="number"
                inputMode="numeric"
                value={newItemQty}
                onChange={(e) => setNewItemQty(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="QTD"
                className="w-14 text-center bg-transparent py-3 text-sm font-bold text-gray-700 outline-none"
              />
              <button 
                onClick={addItem}
                className="h-full px-4 bg-blue-600 text-white active:bg-blue-700 transition-colors flex items-center justify-center border-l border-blue-500"
                aria-label="Adicionar item"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>
          </div>
          {feedback && (
            <p className="text-amber-600 text-[10px] mt-2 px-1 font-bold uppercase animate-pulse">
              {feedback}
            </p>
          )}
        </div>

        {/* Search Bar - Discreet */}
        <div className="relative px-1">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar item..."
            className="w-full bg-gray-100/50 border-none rounded-xl py-2 pl-10 pr-4 text-xs focus:ring-1 focus:ring-gray-200 transition-all outline-none"
          />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          {searchTerm && (
            <button 
              onClick={() => setSearchTerm('')}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          )}
        </div>

        <div className="flex items-center justify-between px-1">
          <span className="text-gray-500 text-[10px] font-bold uppercase tracking-widest">
            {searchTerm ? `Resultados: ${sections.available.length + sections.unavailable.length}` : 'Sua Lista'}
          </span>
          <select 
            value={settings.sortMode}
            onChange={(e) => setSettings({...settings, sortMode: e.target.value as SortMode})}
            className="text-[10px] bg-transparent border-none text-blue-600 font-bold uppercase focus:ring-0 cursor-pointer tracking-wider"
          >
            <option value={SortMode.NameAZ}>A–Z</option>
            <option value={SortMode.PriceAsc}>$ Menor</option>
            <option value={SortMode.PriceDesc}>$ Maior</option>
            <option value={SortMode.Newest}>Recentes</option>
          </select>
        </div>

        <div className="space-y-6">
          {sections.available.length === 0 && sections.unavailable.length === 0 ? (
            <div className="text-center py-12 opacity-40">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
              </svg>
              <p className="text-xs uppercase font-bold tracking-widest">Nenhum item encontrado</p>
            </div>
          ) : (
            <>
              {/* Available Section */}
              {sections.available.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Itens disponíveis</span>
                  </div>
                  {sections.available.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                    />
                  ))}
                </div>
              )}

              {/* Unavailable Section */}
              {sections.unavailable.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-gray-400 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Itens indisponíveis</span>
                  </div>
                  {sections.unavailable.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                    />
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </main>

      {/* Undo Toast */}
      {lastDeletedItem && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-sm z-[80] animate-in slide-in-from-bottom duration-300">
          <div className="bg-gray-900 text-white px-4 py-3 rounded-2xl flex items-center justify-between shadow-xl">
            <span className="text-sm font-medium">Item removido: <b>{lastDeletedItem.name}</b></span>
            <button 
              onClick={undoDelete}
              className="text-blue-400 font-bold text-sm uppercase tracking-wider active:scale-90 transition-transform"
            >
              Desfazer
            </button>
          </div>
        </div>
      )}

      {/* Quick View FAB */}
      <button 
        onClick={() => setShowQuickView(true)}
        className="fixed bottom-24 right-4 w-12 h-12 bg-white shadow-lg border border-gray-100 rounded-full flex items-center justify-center text-blue-600 active:scale-90 transition-transform z-20"
        aria-label="Visualização rápida"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
        </svg>
      </button>

      {/* Footer Total */}
      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-4 flex flex-col items-center shadow-[0_-4px_10px_rgba(0,0,0,0.03)] z-30 transition-colors ${budgetExceeded ? 'border-red-500 bg-red-50' : ''}`}>
        <div className="w-full flex justify-between items-center">
          <div className="flex flex-col">
            <span className={`font-medium text-xs uppercase tracking-widest ${budgetExceeded ? 'text-red-600' : 'text-gray-500'}`}>Total Estimado</span>
            {settings.isBudgetModeActive && (
              <span className="text-[10px] text-gray-400 font-bold uppercase">Orçamento: R$ {settings.budgetLimit.toFixed(2)}</span>
            )}
          </div>
          <span className={`font-bold transition-colors ${budgetExceeded ? 'text-red-600' : 'text-blue-600'} ${settings.textSize === 'large' ? 'text-2xl' : 'text-xl'}`}>
            R$ {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
        {budgetExceeded && (
          <p className="text-[10px] text-red-600 font-bold uppercase mt-1 tracking-tighter animate-pulse">
            Você ultrapassou seu orçamento
          </p>
        )}
      </footer>

      {/* Modals */}
      {showSettings && (
        <SettingsModal 
          settings={settings} 
          onUpdate={(s) => setSettings(s)} 
          onClose={() => setShowSettings(false)} 
        />
      )}
      {showQuickView && (
        <QuickView 
          items={items} 
          total={totalValue} 
          onClose={() => setShowQuickView(false)} 
          textSizeClass={textSizeClass}
        />
      )}

      {/* Clear List Confirmation Modal */}
      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-sm rounded-[2rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </div>
            <h2 className="text-xl font-bold text-gray-900 text-center mb-2">Limpar lista?</h2>
            <p className="text-gray-500 text-center text-sm mb-8 leading-relaxed">Isso removerá permanentemente todos os itens da sua lista de compras.</p>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => setShowClearConfirm(false)}
                className="py-4 bg-gray-100 text-gray-700 font-bold rounded-xl active:bg-gray-200 transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleClearList}
                className="py-4 bg-[#dc2626] text-white font-bold rounded-xl active:scale-95 transition-transform"
              >
                Sim, limpar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export type TextSize = 'small' | 'medium' | 'large';

export enum SortMode {
  NameAZ = 'NameAZ',
  PriceAsc = 'PriceAsc',
  PriceDesc = 'PriceDesc',
  Newest = 'Newest'
}

export interface ShoppingItem {
  id: string;
  name: string;
  quantity: number;
  unitPrice: number;
  isAvailable: boolean;
  addedAt: number;
}

export interface AppSettings {
  textSize: TextSize;
  sortMode: SortMode;
  isBudgetModeActive: boolean;
  budgetLimit: number;
  isHapticEnabled: boolean;
  currency: string;
}

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, TextSize, SortMode, AppSettings } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { QuickView } from './components/QuickView';
import { SettingsModal } from './components/SettingsModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

const App: React.FC = () => {
  // --- State ---
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    isHapticEnabled: true,
    currency: 'R$',
  });
  const [newItemName, setNewItemName] = useState('');
  const [newItemQty, setNewItemQty] = useState<string>('1');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showQuickView, setShowQuickView] = useState(false);
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  // Undo Logic State
  const [lastDeletedItem, setLastDeletedItem] = useState<ShoppingItem | null>(null);
  const undoTimeoutRef = useRef<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      setSettings(prev => ({
        ...prev,
        ...parsed
      }));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  // --- Haptic Feedback Helper ---
  const triggerVibration = useCallback(() => {
    if (settings.isHapticEnabled && 'vibrate' in navigator) {
      navigator.vibrate(30); 
    }
  }, [settings.isHapticEnabled]);

  // --- Logic ---
  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;

    const exists = items.find(i => i.name.toLowerCase() === name.toLowerCase());
    if (exists) {
      setFeedback('Este item já está na sua lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const qty = parseInt(newItemQty) || 1;

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: qty,
      unitPrice: 0,
      isAvailable: true,
      addedAt: Date.now()
    };

    triggerVibration(); 
    setItems(prev => [newItem, ...prev]);
    setNewItemName('');
    setNewItemQty('1');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, items, triggerVibration]);

  const updateItem = useCallback((id: string, updates: Partial<ShoppingItem>) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
  }, []);

  const deleteItem = useCallback((id: string) => {
    const itemToDelete = items.find(i => i.id === id);
    if (itemToDelete) {
      triggerVibration(); 
      setLastDeletedItem(itemToDelete);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
      undoTimeoutRef.current = window.setTimeout(() => {
        setLastDeletedItem(null);
      }, 5000);

      setItems(prev => prev.filter(item => item.id !== id));
    }
  }, [items, triggerVibration]);

  const undoDelete = useCallback(() => {
    if (lastDeletedItem) {
      triggerVibration(); 
      setItems(prev => [lastDeletedItem, ...prev]);
      setLastDeletedItem(null);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    }
  }, [lastDeletedItem, triggerVibration]);

  const handleClearList = useCallback(() => {
    triggerVibration();
    setItems([]);
    setShowClearConfirm(false);
  }, [triggerVibration]);

  const sections = useMemo(() => {
    let filtered = items.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    switch (settings.sortMode) {
      case SortMode.NameAZ:
        filtered.sort((a, b) => a.name.localeCompare(b.name));
        break;
      case SortMode.PriceAsc:
        filtered.sort((a, b) => (a.unitPrice * a.quantity) - (b.unitPrice * b.quantity));
        break;
      case SortMode.PriceDesc:
        filtered.sort((a, b) => (b.unitPrice * b.quantity) - (a.unitPrice * a.quantity));
        break;
      case SortMode.Newest:
        filtered.sort((a, b) => b.addedAt - a.addedAt);
        break;
    }

    return {
      available: filtered.filter(i => i.isAvailable),
      unavailable: filtered.filter(i => !i.isAvailable)
    };
  }, [items, searchTerm, settings.sortMode]);

  const totalValue = useMemo(() => {
    return items
      .filter(i => i.isAvailable)
      .reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0);
  }, [items]);

  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  const availableCount = items.filter(i => i.isAvailable).length;

  const textSizeClass = settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base';
  const titleSizeClass = settings.textSize === 'small' ? 'text-base' : settings.textSize === 'large' ? 'text-xl' : 'text-lg';

  // Helper for formatting currency
  const formatValue = (val: number) => {
    return val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${textSizeClass}`}>
      {/* Header */}
      <Header 
        itemCount={items.length} 
        availableCount={availableCount}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
      />

      {/* Main Content */}
      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {/* Input Section - Refined to include QTD input */}
        <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
          <div className="flex gap-2">
            <div className="flex-1 relative">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que você precisa?"
                className="w-full px-4 py-3 rounded-xl border-gray-200 border bg-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
              />
            </div>

            <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner">
              <input
                type="number"
                inputMode="numeric"
                value={newItemQty}
                onChange={(e) => setNewItemQty(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="QTD"
                className="w-14 text-center bg-transparent py-3 text-sm font-bold text-gray-700 outline-none"
              />
              <button 
                onClick={addItem}
                className="h-full px-4 bg-blue-600 text-white active:bg-blue-700 transition-colors flex items-center justify-center border-l border-blue-500"
                aria-label="Adicionar item"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>
          </div>
          {feedback && (
            <p className="text-amber-600 text-[10px] mt-2 px-1 font-bold uppercase animate-pulse">
              {feedback}
            </p>
          )}
        </div>

        {/* Search Bar - Discreet */}
        <div className="relative px-1">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar item..."
            className="w-full bg-gray-100/50 border-none rounded-xl py-2 pl-10 pr-4 text-xs focus:ring-1 focus:ring-gray-200 transition-all outline-none"
          />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          {searchTerm && (
            <button 
              onClick={() => setSearchTerm('')}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          )}
        </div>

        <div className="flex items-center justify-between px-1">
          <span className="text-gray-500 text-[10px] font-bold uppercase tracking-widest">
            {searchTerm ? `Resultados: ${sections.available.length + sections.unavailable.length}` : 'Sua Lista'}
          </span>
          <select 
            value={settings.sortMode}
            onChange={(e) => setSettings({...settings, sortMode: e.target.value as SortMode})}
            className="text-[10px] bg-transparent border-none text-blue-600 font-bold uppercase focus:ring-0 cursor-pointer tracking-wider"
          >
            <option value={SortMode.NameAZ}>A–Z</option>
            <option value={SortMode.PriceAsc}>$ Menor</option>
            <option value={SortMode.PriceDesc}>$ Maior</option>
            <option value={SortMode.Newest}>Recentes</option>
          </select>
        </div>

        <div className="space-y-6">
          {sections.available.length === 0 && sections.unavailable.length === 0 ? (
            <div className="text-center py-12 opacity-40">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
              </svg>
              <p className="text-xs uppercase font-bold tracking-widest">Nenhum item encontrado</p>
            </div>
          ) : (
            <>
              {/* Available Section */}
              {sections.available.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Itens disponíveis</span>
                  </div>
                  {sections.available.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                      currency={settings.currency}
                    />
                  ))}
                </div>
              )}

              {/* Unavailable Section */}
              {sections.unavailable.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-gray-400 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Itens indisponíveis</span>
                  </div>
                  {sections.unavailable.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                      currency={settings.currency}
                    />
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </main>

      {/* Undo Toast */}
      {lastDeletedItem && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-sm z-[80] animate-in slide-in-from-bottom duration-300">
          <div className="bg-gray-900 text-white px-4 py-3 rounded-2xl flex items-center justify-between shadow-xl">
            <span className="text-sm font-medium">Item removido: <b>{lastDeletedItem.name}</b></span>
            <button 
              onClick={undoDelete}
              className="text-blue-400 font-bold text-sm uppercase tracking-wider active:scale-90 transition-transform"
            >
              Desfazer
            </button>
          </div>
        </div>
      )}

      {/* Quick View FAB */}
      <button 
        onClick={() => setShowQuickView(true)}
        className="fixed bottom-24 right-4 w-12 h-12 bg-white shadow-lg border border-gray-100 rounded-full flex items-center justify-center text-blue-600 active:scale-90 transition-transform z-20"
        aria-label="Visualização rápida"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
        </svg>
      </button>

      {/* Footer Total */}
      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-4 flex flex-col items-center shadow-[0_-4px_10px_rgba(0,0,0,0.03)] z-30 transition-colors ${budgetExceeded ? 'border-red-500 bg-red-50' : ''}`}>
        <div className="w-full flex justify-between items-center">
          <div className="flex flex-col">
            <span className={`font-medium text-xs uppercase tracking-widest ${budgetExceeded ? 'text-red-600' : 'text-gray-500'}`}>Total Estimado</span>
            {settings.isBudgetModeActive && (
              <span className="text-[10px] text-gray-400 font-bold uppercase">Orçamento: {settings.currency} {settings.budgetLimit.toFixed(2)}</span>
            )}
          </div>
          <span className={`font-bold transition-colors ${budgetExceeded ? 'text-red-600' : 'text-blue-600'} ${settings.textSize === 'large' ? 'text-2xl' : 'text-xl'}`}>
            {settings.currency} {formatValue(totalValue)}
          </span>
        </div>
        {budgetExceeded && (
          <p className="text-[10px] text-red-600 font-bold uppercase mt-1 tracking-tighter animate-pulse">
            Você ultrapassou seu orçamento
          </p>
        )}
      </footer>

      {/* Modals */}
      {showSettings && (
        <SettingsModal 
          settings={settings} 
          onUpdate={(s) => setSettings(s)} 
          onClose={() => setShowSettings(false)} 
        />
      )}
      {showQuickView && (
        <QuickView 
          items={items} 
          total={totalValue} 
          onClose={() => setShowQuickView(false)} 
          textSizeClass={textSizeClass}
          currency={settings.currency}
        />
      )}

      {/* Clear List Confirmation Modal */}
      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-sm rounded-[2rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </div>
            <h2 className="text-xl font-bold text-gray-900 text-center mb-2">Limpar lista?</h2>
            <p className="text-gray-500 text-center text-sm mb-8 leading-relaxed">Isso removerá permanentemente todos os itens da sua lista de compras.</p>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => setShowClearConfirm(false)}
                className="py-4 bg-gray-100 text-gray-700 font-bold rounded-xl active:bg-gray-200 transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleClearList}
                className="py-4 bg-[#dc2626] text-white font-bold rounded-xl active:scale-95 transition-transform"
              >
                Sim, limpar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { AppSettings, TextSize } from '../types';

interface SettingsModalProps {
  settings: AppSettings;
  onUpdate: (s: AppSettings) => void;
  onClose: () => void;
}

export const SettingsModal: React.FC<SettingsModalProps> = ({ settings, onUpdate, onClose }) => {
  const [displayBudget, setDisplayBudget] = useState(
    settings.budgetLimit === 0 ? '' : settings.budgetLimit.toString().replace('.', ',')
  );

  useEffect(() => {
    const formatted = settings.budgetLimit === 0 ? '' : settings.budgetLimit.toString().replace('.', ',');
    const currentNumeric = parseFloat(displayBudget.replace(',', '.'));
    const isSameValue = isNaN(currentNumeric) ? settings.budgetLimit === 0 : currentNumeric === settings.budgetLimit;

    if (!isSameValue) {
      setDisplayBudget(formatted);
    }
  }, [settings.budgetLimit]);

  const sizes: { value: TextSize; label: string; desc: string }[] = [
    { value: 'small', label: 'Pequeno', desc: 'Minimalista' },
    { value: 'medium', label: 'Médio', desc: 'Padrão' },
    { value: 'large', label: 'Grande', desc: 'Acessível' },
  ];

  const currencies = ['R$', '$', '€', '£'];

  const handleBudgetChange = (val: string) => {
    const cleanVal = val.replace(/[^0-9.,]/g, '');
    const parts = cleanVal.split(/[.,]/);
    if (parts.length > 2) return;

    setDisplayBudget(cleanVal);
    const normalized = cleanVal.replace(',', '.');
    const budget = parseFloat(normalized);
    onUpdate({ ...settings, budgetLimit: isNaN(budget) ? 0 : budget });
  };

  const handleHapticToggle = () => {
    const nextValue = !settings.isHapticEnabled;
    if (nextValue && 'vibrate' in navigator) {
      navigator.vibrate(30);
    }
    onUpdate({ ...settings, isHapticEnabled: nextValue });
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-end sm:items-center justify-center p-0 sm:p-4 animate-in fade-in duration-200">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-white w-full max-w-md rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-bottom duration-300">
        <div className="w-12 h-1.5 bg-gray-200 rounded-full mx-auto mb-6 sm:hidden" onClick={onClose} />
        <h2 className="text-xl font-bold text-gray-900 mb-6">Configurações</h2>

        <div className="space-y-8 overflow-y-auto max-h-[70vh] pb-4">
          {/* Text Size Section */}
          <div>
            <label className="text-xs font-bold text-gray-400 uppercase tracking-widest block mb-4">Tamanho do Texto</label>
            <div className="grid grid-cols-3 gap-3">
              {sizes.map(size => (
                <button
                  key={size.value}
                  onClick={() => onUpdate({ ...settings, textSize: size.value })}
                  className={`flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all ${
                    settings.textSize === size.value 
                    ? 'border-blue-600 bg-blue-50 text-blue-700' 
                    : 'border-gray-100 bg-gray-50 text-gray-400'
                  }`}
                >
                  <span className={`font-bold ${size.value === 'large' ? 'text-lg' : size.value === 'small' ? 'text-xs' : 'text-sm'}`}>Aa</span>
                  <span className="text-[10px] mt-1 font-semibold uppercase">{size.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Currency Selection Section */}
          <div>
            <label className="text-xs font-bold text-gray-400 uppercase tracking-widest block mb-4">Moeda Preferencial</label>
            <div className="flex gap-3">
              {currencies.map(curr => (
                <button
                  key={curr}
                  onClick={() => onUpdate({ ...settings, currency: curr })}
                  className={`flex-1 py-3 rounded-2xl border-2 transition-all font-bold ${
                    settings.currency === curr
                    ? 'border-blue-600 bg-blue-50 text-blue-700'
                    : 'border-gray-100 bg-gray-50 text-gray-400'
                  }`}
                >
                  {curr}
                </button>
              ))}
            </div>
          </div>

          {/* Budget and Haptic Section */}
          <div className="space-y-4">
            {/* Budget Mode Toggle */}
            <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
              <div className="flex justify-between items-center mb-4">
                <div>
                  <label className="text-xs font-bold text-gray-900 uppercase tracking-tight block">Modo Orçamento</label>
                  <p className="text-[10px] text-gray-400 font-medium">Controle seus gastos totais</p>
                </div>
                <button 
                  onClick={() => onUpdate({ ...settings, isBudgetModeActive: !settings.isBudgetModeActive })}
                  className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${settings.isBudgetModeActive ? 'bg-blue-600' : 'bg-gray-300'}`}
                >
                  <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${settings.isBudgetModeActive ? 'translate-x-6' : 'translate-x-0'}`} />
                </button>
              </div>

              {settings.isBudgetModeActive && (
                <div className="mt-4 animate-in slide-in-from-top duration-200">
                  <label className="text-[10px] text-gray-400 font-bold uppercase block mb-1">Valor Máximo</label>
                  <div className="relative">
                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 text-sm font-medium">{settings.currency}</span>
                    <input
                      type="text"
                      inputMode="decimal"
                      value={displayBudget}
                      onChange={(e) => handleBudgetChange(e.target.value)}
                      placeholder="0,00"
                      className="w-full pl-11 pr-4 py-3 bg-white border border-gray-200 rounded-xl text-left font-bold text-gray-700 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                    />
                  </div>
                </div>
              )}
            </div>

            {/* Haptic Feedback Toggle */}
            <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100 flex justify-between items-center">
              <div>
                <label className="text-xs font-bold text-gray-900 uppercase tracking-tight block">Feedback Tátil</label>
                <p className="text-[10px] text-gray-400 font-medium">Vibração leve ao interagir</p>
              </div>
              <button 
                onClick={handleHapticToggle}
                className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${settings.isHapticEnabled ? 'bg-blue-600' : 'bg-gray-300'}`}
              >
                <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${settings.isHapticEnabled ? 'translate-x-6' : 'translate-x-0'}`} />
              </button>
            </div>
          </div>

          <div className="pt-2 border-t border-gray-100">
             <button 
              onClick={onClose}
              className="w-full py-4 bg-gray-900 text-white font-bold rounded-2xl active:scale-95 transition-transform shadow-lg shadow-gray-200"
            >
              Confirmar
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { ShoppingItem } from '../types';

interface ItemCardProps {
  item: ShoppingItem;
  onUpdate: (updates: Partial<ShoppingItem>) => void;
  onDelete: () => void;
  textSizeClass: string;
  titleSizeClass: string;
  isHapticEnabled: boolean;
  currency: string;
}

export const ItemCard: React.FC<ItemCardProps> = ({ item, onUpdate, onDelete, textSizeClass, titleSizeClass, isHapticEnabled, currency }) => {
  const timerRef = useRef<number | null>(null);

  // Local state for the input to handle typing commas/dots smoothly without cursor jumps
  const [displayPrice, setDisplayPrice] = useState(
    item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',')
  );

  // Sync display price if item.unitPrice changes externally (e.g., clearing the list)
  useEffect(() => {
    const formatted = item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',');
    // Parse current display price to check if it represents the same numeric value
    const currentNumeric = parseFloat(displayPrice.replace(',', '.'));
    const isSameValue = isNaN(currentNumeric) ? item.unitPrice === 0 : currentNumeric === item.unitPrice;

    if (!isSameValue) {
      setDisplayPrice(formatted);
    }
  }, [item.unitPrice]);

  const triggerVibration = () => {
    if (isHapticEnabled && 'vibrate' in navigator) {
      navigator.vibrate(30); 
    }
  };

  const handlePriceChange = (val: string) => {
    // Only allow digits and a single comma or dot
    const cleanVal = val.replace(/[^0-9.,]/g, '');

    // Split by possible separators to ensure only one exists
    const parts = cleanVal.split(/[.,]/);
    if (parts.length > 2) return;

    setDisplayPrice(cleanVal);

    // Normalize to standard float format for storage
    const normalized = cleanVal.replace(',', '.');
    const price = parseFloat(normalized);
    onUpdate({ unitPrice: isNaN(price) ? 0 : price });
  };

  const handleLongPressStart = () => {
    timerRef.current = window.setTimeout(() => {
      // Long press logic if needed
    }, 800);
  };

  const handleLongPressEnd = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
  };

  const total = item.unitPrice * item.quantity;

  return (
    <div 
      className={`bg-white rounded-2xl p-4 border border-gray-100 shadow-sm transition-all duration-300 relative overflow-hidden ${!item.isAvailable ? 'opacity-50' : 'opacity-100'}`}
      onTouchStart={handleLongPressStart}
      onTouchEnd={handleLongPressEnd}
      onMouseDown={handleLongPressStart}
      onMouseUp={handleLongPressEnd}
    >
      <div className="flex flex-col gap-3">
        {/* Top Row: Name, Delete Icon and Availability Toggle */}
        <div className="flex justify-between items-start gap-2">
          <h3 className={`font-bold flex-1 break-words ${titleSizeClass} ${!item.isAvailable ? 'line-through text-gray-400' : 'text-gray-900'}`}>
            {item.name}
          </h3>
          <div className="flex items-center gap-3 shrink-0">
            <button 
              onClick={(e) => {
                e.stopPropagation();
                onDelete();
              }}
              className="p-1.5 text-gray-300 hover:text-red-500 active:text-red-600 transition-colors"
              aria-label="Excluir item"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
            <button 
              onClick={() => {
                triggerVibration(); 
                onUpdate({ isAvailable: !item.isAvailable });
              }}
              className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${item.isAvailable ? 'bg-blue-600' : 'bg-gray-300'}`}
            >
              <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${item.isAvailable ? 'translate-x-6' : 'translate-x-0'}`} />
            </button>
          </div>
        </div>

        {/* Middle Row: Controls */}
        <div className="flex items-center justify-between gap-2">
          {/* Quantity Controls */}
          <div className="flex items-center bg-gray-50 rounded-xl p-1 border border-gray-100">
            <button 
              onClick={() => {
                triggerVibration();
                onUpdate({ quantity: Math.max(1, item.quantity - 1) });
              }}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              −
            </button>
            <span className="w-10 text-center font-bold text-gray-700">{item.quantity}</span>
            <button 
              onClick={() => {
                triggerVibration();
                onUpdate({ quantity: item.quantity + 1 });
              }}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              +
            </button>
          </div>

          {/* Price Input */}
          <div className="flex-1 max-w-[130px]">
            <label className="text-[10px] text-gray-400 font-bold uppercase block mb-1 text-center">Preço Unitário</label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs font-medium">{currency}</span>
              <input
                type="text"
                inputMode="decimal"
                value={displayPrice}
                onChange={(e) => handlePriceChange(e.target.value)}
                placeholder="0,00"
                className="w-full pl-9 pr-3 py-2 bg-gray-50 border border-gray-100 rounded-xl text-right font-semibold text-gray-700 focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500 focus:bg-white outline-none transition-all shadow-sm"
              />
            </div>
          </div>
        </div>

        {/* Bottom Row: Total */}
        <div className="pt-2 border-t border-gray-50 flex justify-between items-center">
          <span className="text-gray-400 text-xs font-medium uppercase tracking-tight">Subtotal</span>
          <span className={`font-bold text-gray-900 ${textSizeClass}`}>
            {currency} {total.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { ShoppingItem } from '../types';

interface QuickViewProps {
  items: ShoppingItem[];
  total: number;
  onClose: () => void;
  textSizeClass: string;
  currency: string;
}

export const QuickView: React.FC<QuickViewProps> = ({ items, total, onClose, textSizeClass, currency }) => {
  // Sort logic: Available items first, then alphabetical within each group
  const sortedItems = useMemo(() => {
    return [...items].sort((a, b) => {
      // Primary sort: isAvailable (true/available comes first)
      if (a.isAvailable && !b.isAvailable) return -1;
      if (!a.isAvailable && b.isAvailable) return 1;

      // Secondary sort: alphabetical by name
      return a.name.localeCompare(b.name);
    });
  }, [items]);

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-white overflow-hidden animate-in slide-in-from-bottom duration-300">
      <div className="bg-blue-600 px-6 py-6 text-white shrink-0">
        <h2 className="text-xl font-bold">Resumo da Compra</h2>
        <p className="text-blue-100 text-xs mt-1 uppercase tracking-widest font-semibold">Modo visualização — para editar, volte à lista</p>
      </div>

      <div className="flex-1 overflow-y-auto px-6 py-4">
        {sortedItems.length === 0 ? (
          <p className="text-center text-gray-400 mt-20 font-medium">Nada para exibir</p>
        ) : (
          <ul className="divide-y divide-gray-100">
            {sortedItems.map(item => (
              <li key={item.id} className={`py-3 flex justify-between items-center transition-opacity ${!item.isAvailable ? 'opacity-30' : ''}`}>
                <span className={`font-medium text-gray-800 ${textSizeClass}`}>
                  {item.quantity}x {item.name}
                </span>
                <span className={`font-bold text-gray-600 ${textSizeClass}`}>
                  {currency} {(item.unitPrice * item.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="p-6 border-t border-gray-100 bg-gray-50 flex flex-col gap-4 shrink-0">
        <div className="flex justify-between items-center px-2">
          <span className="text-gray-500 font-semibold uppercase text-xs">Total Geral</span>
          <span className="text-2xl font-black text-gray-900">
            {currency} {total.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
        <button 
          onClick={onClose}
          className="w-full py-4 bg-blue-600 text-white font-bold rounded-2xl active:scale-95 transition-transform shadow-lg shadow-blue-200"
        >
          Voltar para Lista
        </button>
      </div>
    </div>
  );
};

export type TextSize = 'small' | 'medium' | 'large';

export enum SortMode {
  NameAZ = 'NameAZ',
  PriceAsc = 'PriceAsc',
  PriceDesc = 'PriceDesc',
  Newest = 'Newest'
}

export interface ShoppingItem {
  id: string;
  name: string;
  quantity: number;
  unitPrice: number;
  isAvailable: boolean;
  isPurchased: boolean;
  addedAt: number;
}

export interface AppSettings {
  textSize: TextSize;
  sortMode: SortMode;
  isBudgetModeActive: boolean;
  budgetLimit: number;
  isHapticEnabled: boolean;
  currency: string;
}

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, TextSize, SortMode, AppSettings } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { QuickView } from './components/QuickView';
import { SettingsModal } from './components/SettingsModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

const App: React.FC = () => {
  // --- State ---
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    isHapticEnabled: true,
    currency: 'R$',
  });
  const [newItemName, setNewItemName] = useState('');
  const [newItemQty, setNewItemQty] = useState<string>('1');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showQuickView, setShowQuickView] = useState(false);
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  // Undo Logic State
  const [lastDeletedItem, setLastDeletedItem] = useState<ShoppingItem | null>(null);
  const undoTimeoutRef = useRef<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      setSettings(prev => ({
        ...prev,
        ...parsed
      }));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  // --- Haptic Feedback Helper ---
  const triggerVibration = useCallback(() => {
    if (settings.isHapticEnabled && 'vibrate' in navigator) {
      navigator.vibrate(30); 
    }
  }, [settings.isHapticEnabled]);

  // --- Logic ---
  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;

    const exists = items.find(i => i.name.toLowerCase() === name.toLowerCase());
    if (exists) {
      setFeedback('Este item já está na sua lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const qty = parseInt(newItemQty) || 1;

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: qty,
      unitPrice: 0,
      isAvailable: true,
      isPurchased: false,
      addedAt: Date.now()
    };

    triggerVibration(); 
    setItems(prev => [newItem, ...prev]);
    setNewItemName('');
    setNewItemQty('1');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, items, triggerVibration]);

  const updateItem = useCallback((id: string, updates: Partial<ShoppingItem>) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
  }, []);

  const deleteItem = useCallback((id: string) => {
    const itemToDelete = items.find(i => i.id === id);
    if (itemToDelete) {
      triggerVibration(); 
      setLastDeletedItem(itemToDelete);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
      undoTimeoutRef.current = window.setTimeout(() => {
        setLastDeletedItem(null);
      }, 5000);

      setItems(prev => prev.filter(item => item.id !== id));
    }
  }, [items, triggerVibration]);

  const undoDelete = useCallback(() => {
    if (lastDeletedItem) {
      triggerVibration(); 
      setItems(prev => [lastDeletedItem, ...prev]);
      setLastDeletedItem(null);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    }
  }, [lastDeletedItem, triggerVibration]);

  const handleClearList = useCallback(() => {
    triggerVibration();
    setItems([]);
    setShowClearConfirm(false);
  }, [triggerVibration]);

  const sections = useMemo(() => {
    let filtered = items.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Common sorting logic
    const sortFn = (a: ShoppingItem, b: ShoppingItem) => {
      switch (settings.sortMode) {
        case SortMode.NameAZ:
          return a.name.localeCompare(b.name);
        case SortMode.PriceAsc:
          return (a.unitPrice * a.quantity) - (b.unitPrice * b.quantity);
        case SortMode.PriceDesc:
          return (b.unitPrice * b.quantity) - (a.unitPrice * a.quantity);
        case SortMode.Newest:
          return b.addedAt - a.addedAt;
        default:
          return 0;
      }
    };

    const available = filtered.filter(i => i.isAvailable && !i.isPurchased).sort(sortFn);
    const purchased = filtered.filter(i => i.isAvailable && i.isPurchased).sort(sortFn);
    const unavailable = filtered.filter(i => !i.isAvailable).sort(sortFn);

    return { available, purchased, unavailable };
  }, [items, searchTerm, settings.sortMode]);

  const totalValue = useMemo(() => {
    return items
      .filter(i => i.isAvailable)
      .reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0);
  }, [items]);

  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  const availableCount = items.filter(i => i.isAvailable).length;

  const textSizeClass = settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base';
  const titleSizeClass = settings.textSize === 'small' ? 'text-base' : settings.textSize === 'large' ? 'text-xl' : 'text-lg';

  const formatValue = (val: number) => {
    return val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${textSizeClass}`}>
      <Header 
        itemCount={items.length} 
        availableCount={availableCount}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
      />

      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
          <div className="flex gap-2">
            <div className="flex-1 relative">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que você precisa?"
                className="w-full px-4 py-3 rounded-xl border-gray-200 border bg-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
              />
            </div>

            <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner">
              <input
                type="number"
                inputMode="numeric"
                value={newItemQty}
                onChange={(e) => setNewItemQty(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="QTD"
                className="w-14 text-center bg-transparent py-3 text-sm font-bold text-gray-700 outline-none"
              />
              <button 
                onClick={addItem}
                className="h-full px-4 bg-blue-600 text-white active:bg-blue-700 transition-colors flex items-center justify-center border-l border-blue-500"
                aria-label="Adicionar item"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>
          </div>
          {feedback && (
            <p className="text-amber-600 text-[10px] mt-2 px-1 font-bold uppercase animate-pulse">
              {feedback}
            </p>
          )}
        </div>

        <div className="relative px-1">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar item..."
            className="w-full bg-gray-100/50 border-none rounded-xl py-2 pl-10 pr-4 text-xs focus:ring-1 focus:ring-gray-200 transition-all outline-none"
          />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          {searchTerm && (
            <button 
              onClick={() => setSearchTerm('')}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          )}
        </div>

        <div className="flex items-center justify-between px-1">
          <span className="text-gray-500 text-[10px] font-bold uppercase tracking-widest">
            {searchTerm ? `Resultados: ${sections.available.length + sections.purchased.length + sections.unavailable.length}` : 'Sua Lista'}
          </span>
          <select 
            value={settings.sortMode}
            onChange={(e) => setSettings({...settings, sortMode: e.target.value as SortMode})}
            className="text-[10px] bg-transparent border-none text-blue-600 font-bold uppercase focus:ring-0 cursor-pointer tracking-wider"
          >
            <option value={SortMode.NameAZ}>A–Z</option>
            <option value={SortMode.PriceAsc}>$ Menor</option>
            <option value={SortMode.PriceDesc}>$ Maior</option>
            <option value={SortMode.Newest}>Recentes</option>
          </select>
        </div>

        <div className="space-y-6">
          {sections.available.length === 0 && sections.purchased.length === 0 && sections.unavailable.length === 0 ? (
            <div className="text-center py-12 opacity-40">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
              </svg>
              <p className="text-xs uppercase font-bold tracking-widest">Nenhum item encontrado</p>
            </div>
          ) : (
            <>
              {/* Not Purchased Section */}
              {sections.available.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-blue-500 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Para Comprar</span>
                  </div>
                  {sections.available.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                      currency={settings.currency}
                    />
                  ))}
                </div>
              )}

              {/* Purchased Section */}
              {sections.purchased.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">No Carrinho</span>
                  </div>
                  {sections.purchased.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                      currency={settings.currency}
                    />
                  ))}
                </div>
              )}

              {/* Unavailable Section */}
              {sections.unavailable.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-gray-400 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Itens indisponíveis</span>
                  </div>
                  {sections.unavailable.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                      currency={settings.currency}
                    />
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </main>

      {lastDeletedItem && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-sm z-[80] animate-in slide-in-from-bottom duration-300">
          <div className="bg-gray-900 text-white px-4 py-3 rounded-2xl flex items-center justify-between shadow-xl">
            <span className="text-sm font-medium">Item removido: <b>{lastDeletedItem.name}</b></span>
            <button 
              onClick={undoDelete}
              className="text-blue-400 font-bold text-sm uppercase tracking-wider active:scale-90 transition-transform"
            >
              Desfazer
            </button>
          </div>
        </div>
      )}

      <button 
        onClick={() => setShowQuickView(true)}
        className="fixed bottom-24 right-4 w-12 h-12 bg-white shadow-lg border border-gray-100 rounded-full flex items-center justify-center text-blue-600 active:scale-90 transition-transform z-20"
        aria-label="Visualização rápida"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
        </svg>
      </button>

      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-4 flex flex-col items-center shadow-[0_-4px_10px_rgba(0,0,0,0.03)] z-30 transition-colors ${budgetExceeded ? 'border-red-500 bg-red-50' : ''}`}>
        <div className="w-full flex justify-between items-center">
          <div className="flex flex-col">
            <span className={`font-medium text-xs uppercase tracking-widest ${budgetExceeded ? 'text-red-600' : 'text-gray-500'}`}>Total Estimado</span>
            {settings.isBudgetModeActive && (
              <span className="text-[10px] text-gray-400 font-bold uppercase">Orçamento: {settings.currency} {settings.budgetLimit.toFixed(2)}</span>
            )}
          </div>
          <span className={`font-bold transition-colors ${budgetExceeded ? 'text-red-600' : 'text-blue-600'} ${settings.textSize === 'large' ? 'text-2xl' : 'text-xl'}`}>
            {settings.currency} {formatValue(totalValue)}
          </span>
        </div>
        {budgetExceeded && (
          <p className="text-[10px] text-red-600 font-bold uppercase mt-1 tracking-tighter animate-pulse">
            Você ultrapassou seu orçamento
          </p>
        )}
      </footer>

      {showSettings && (
        <SettingsModal 
          settings={settings} 
          onUpdate={(s) => setSettings(s)} 
          onClose={() => setShowSettings(false)} 
        />
      )}
      {showQuickView && (
        <QuickView 
          items={items} 
          total={totalValue} 
          onClose={() => setShowQuickView(false)} 
          textSizeClass={textSizeClass}
          currency={settings.currency}
        />
      )}

      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-sm rounded-[2rem] p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </div>
            <h2 className="text-xl font-bold text-gray-900 text-center mb-2">Limpar lista?</h2>
            <p className="text-gray-500 text-center text-sm mb-8 leading-relaxed">Isso removerá permanentemente todos os itens da sua lista de compras.</p>
            <div className="grid grid-cols-2 gap-3">
              <button 
                onClick={() => setShowClearConfirm(false)}
                className="py-4 bg-gray-100 text-gray-700 font-bold rounded-xl active:bg-gray-200 transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleClearList}
                className="py-4 bg-[#dc2626] text-white font-bold rounded-xl active:scale-95 transition-transform"
              >
                Sim, limpar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useRef, useState, useEffect } from 'react';
import { ShoppingItem } from '../types';

interface ItemCardProps {
  item: ShoppingItem;
  onUpdate: (updates: Partial<ShoppingItem>) => void;
  onDelete: () => void;
  textSizeClass: string;
  titleSizeClass: string;
  isHapticEnabled: boolean;
  currency: string;
}

export const ItemCard: React.FC<ItemCardProps> = ({ item, onUpdate, onDelete, textSizeClass, titleSizeClass, isHapticEnabled, currency }) => {
  const timerRef = useRef<number | null>(null);

  const [displayPrice, setDisplayPrice] = useState(
    item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',')
  );

  useEffect(() => {
    const formatted = item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',');
    const currentNumeric = parseFloat(displayPrice.replace(',', '.'));
    const isSameValue = isNaN(currentNumeric) ? item.unitPrice === 0 : currentNumeric === item.unitPrice;

    if (!isSameValue) {
      setDisplayPrice(formatted);
    }
  }, [item.unitPrice]);

  const triggerVibration = () => {
    if (isHapticEnabled && 'vibrate' in navigator) {
      navigator.vibrate(30); 
    }
  };

  const handlePriceChange = (val: string) => {
    const cleanVal = val.replace(/[^0-9.,]/g, '');
    const parts = cleanVal.split(/[.,]/);
    if (parts.length > 2) return;

    setDisplayPrice(cleanVal);
    const normalized = cleanVal.replace(',', '.');
    const price = parseFloat(normalized);
    onUpdate({ unitPrice: isNaN(price) ? 0 : price });
  };

  const handleLongPressStart = () => {
    timerRef.current = window.setTimeout(() => {
    }, 800);
  };

  const handleLongPressEnd = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
  };

  const total = item.unitPrice * item.quantity;

  return (
    <div 
      className={`bg-white rounded-2xl p-4 border border-gray-100 shadow-sm transition-all duration-300 relative overflow-hidden ${!item.isAvailable ? 'opacity-50 grayscale' : 'opacity-100'} ${item.isPurchased && item.isAvailable ? 'bg-green-50/30' : ''}`}
      onTouchStart={handleLongPressStart}
      onTouchEnd={handleLongPressEnd}
      onMouseDown={handleLongPressStart}
      onMouseUp={handleLongPressEnd}
    >
      <div className="flex flex-col gap-3">
        <div className="flex justify-between items-start gap-2">
          <div className="flex items-center gap-2 flex-1">
             {item.isAvailable && (
              <button 
                onClick={() => {
                  triggerVibration();
                  onUpdate({ isPurchased: !item.isPurchased });
                }}
                className={`shrink-0 p-1.5 rounded-lg transition-colors ${item.isPurchased ? 'text-green-600 bg-green-100' : 'text-gray-300 bg-gray-50 active:bg-blue-50'}`}
                aria-label={item.isPurchased ? "Remover do carrinho" : "Adicionar ao carrinho"}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
                </svg>
              </button>
            )}
            <h3 className={`font-bold flex-1 break-words transition-all ${titleSizeClass} ${!item.isAvailable ? 'line-through text-gray-400' : item.isPurchased ? 'text-green-700' : 'text-gray-900'}`}>
              {item.name}
            </h3>
          </div>

          <div className="flex items-center gap-3 shrink-0">
            <button 
              onClick={(e) => {
                e.stopPropagation();
                onDelete();
              }}
              className="p-1.5 text-gray-300 hover:text-red-500 active:text-red-600 transition-colors"
              aria-label="Excluir item"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
            <button 
              onClick={() => {
                triggerVibration(); 
                onUpdate({ isAvailable: !item.isAvailable });
              }}
              className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${item.isAvailable ? 'bg-blue-600' : 'bg-gray-300'}`}
            >
              <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${item.isAvailable ? 'translate-x-6' : 'translate-x-0'}`} />
            </button>
          </div>
        </div>

        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center bg-gray-50 rounded-xl p-1 border border-gray-100">
            <button 
              onClick={() => {
                triggerVibration();
                onUpdate({ quantity: Math.max(1, item.quantity - 1) });
              }}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              −
            </button>
            <span className="w-10 text-center font-bold text-gray-700">{item.quantity}</span>
            <button 
              onClick={() => {
                triggerVibration();
                onUpdate({ quantity: item.quantity + 1 });
              }}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              +
            </button>
          </div>

          <div className="flex-1 max-w-[130px]">
            <label className="text-[10px] text-gray-400 font-bold uppercase block mb-1 text-center">Preço Unitário</label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs font-medium">{currency}</span>
              <input
                type="text"
                inputMode="decimal"
                value={displayPrice}
                onChange={(e) => handlePriceChange(e.target.value)}
                placeholder="0,00"
                className="w-full pl-9 pr-3 py-2 bg-gray-50 border border-gray-100 rounded-xl text-right font-semibold text-gray-700 focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500 focus:bg-white outline-none transition-all shadow-sm"
              />
            </div>
          </div>
        </div>

        <div className="pt-2 border-t border-gray-50 flex justify-between items-center">
          <span className="text-gray-400 text-xs font-medium uppercase tracking-tight">Subtotal</span>
          <span className={`font-bold transition-colors ${item.isPurchased && item.isAvailable ? 'text-green-600' : 'text-gray-900'} ${textSizeClass}`}>
            {currency} {total.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import { ShoppingItem } from '../types';

interface QuickViewProps {
  items: ShoppingItem[];
  total: number;
  onClose: () => void;
  textSizeClass: string;
  currency: string;
}

export const QuickView: React.FC<QuickViewProps> = ({ items, total, onClose, textSizeClass, currency }) => {
  const sortedItems = useMemo(() => {
    return [...items].sort((a, b) => {
      if (!a.isAvailable && b.isAvailable) return 1;
      if (a.isAvailable && !b.isAvailable) return -1;

      if (a.isPurchased && !b.isPurchased) return 1;
      if (!a.isPurchased && b.isPurchased) return -1;

      return a.name.localeCompare(b.name);
    });
  }, [items]);

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-white overflow-hidden animate-in slide-in-from-bottom duration-300">
      <div className="bg-blue-600 px-6 py-6 text-white shrink-0">
        <h2 className="text-xl font-bold">Resumo da Compra</h2>
        <p className="text-blue-100 text-xs mt-1 uppercase tracking-widest font-semibold">Modo visualização — para editar, volte à lista</p>
      </div>

      <div className="flex-1 overflow-y-auto px-6 py-4">
        {sortedItems.length === 0 ? (
          <p className="text-center text-gray-400 mt-20 font-medium">Nada para exibir</p>
        ) : (
          <ul className="divide-y divide-gray-100">
            {sortedItems.map(item => (
              <li key={item.id} className={`py-3 flex justify-between items-center transition-all ${!item.isAvailable ? 'opacity-30' : ''}`}>
                <div className="flex flex-col">
                  <span className={`font-medium text-gray-800 ${textSizeClass}`}>
                    {item.quantity}x {item.name}
                  </span>
                  {item.isPurchased && item.isAvailable && (
                    <span className="text-[10px] text-green-600 font-bold uppercase tracking-tight">Comprado</span>
                  )}
                </div>
                <span className={`font-bold transition-colors ${item.isPurchased && item.isAvailable ? 'text-green-600' : 'text-gray-600'} ${textSizeClass}`}>
                  {currency} {(item.unitPrice * item.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>

      <div className="p-6 border-t border-gray-100 bg-gray-50 flex flex-col gap-4 shrink-0">
        <div className="flex justify-between items-center px-2">
          <span className="text-gray-500 font-semibold uppercase text-xs">Total Geral</span>
          <span className="text-2xl font-black text-gray-900">
            {currency} {total.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
        <button 
          onClick={onClose}
          className="w-full py-4 bg-blue-600 text-white font-bold rounded-2xl active:scale-95 transition-transform shadow-lg shadow-blue-200"
        >
          Voltar para Lista
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, TextSize, SortMode, AppSettings } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { QuickView } from './components/QuickView';
import { SettingsModal } from './components/SettingsModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

type ClearSelection = 'all' | 'purchased' | 'unavailable' | null;

const App: React.FC = () => {
  // --- State ---
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    isHapticEnabled: true,
    currency: 'R$',
  });
  const [newItemName, setNewItemName] = useState('');
  const [newItemQty, setNewItemQty] = useState<string>('1');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showQuickView, setShowQuickView] = useState(false);

  // Clear List Logic State
  const [clearSelection, setClearSelection] = useState<ClearSelection>(null);
  const [showClearConfirm, setShowClearConfirm] = useState(false);

  // Undo Logic State
  const [lastDeletedItem, setLastDeletedItem] = useState<ShoppingItem | null>(null);
  const undoTimeoutRef = useRef<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);

  // --- Persistence ---
  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems));
    if (savedSettings) {
      const parsed = JSON.parse(savedSettings);
      setSettings(prev => ({
        ...prev,
        ...parsed
      }));
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  }, [settings]);

  // --- Haptic Feedback Helper ---
  const triggerVibration = useCallback(() => {
    if (settings.isHapticEnabled && 'vibrate' in navigator) {
      navigator.vibrate(30); 
    }
  }, [settings.isHapticEnabled]);

  // --- Logic ---
  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;

    const exists = items.find(i => i.name.toLowerCase() === name.toLowerCase());
    if (exists) {
      setFeedback('Este item já está na sua lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const qty = parseInt(newItemQty) || 1;

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: qty,
      unitPrice: 0,
      isAvailable: true,
      isPurchased: false,
      addedAt: Date.now()
    };

    triggerVibration(); 
    setItems(prev => [newItem, ...prev]);
    setNewItemName('');
    setNewItemQty('1');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, items, triggerVibration]);

  const updateItem = useCallback((id: string, updates: Partial<ShoppingItem>) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item));
  }, []);

  const deleteItem = useCallback((id: string) => {
    const itemToDelete = items.find(i => i.id === id);
    if (itemToDelete) {
      triggerVibration(); 
      setLastDeletedItem(itemToDelete);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
      undoTimeoutRef.current = window.setTimeout(() => {
        setLastDeletedItem(null);
      }, 5000);

      setItems(prev => prev.filter(item => item.id !== id));
    }
  }, [items, triggerVibration]);

  const undoDelete = useCallback(() => {
    if (lastDeletedItem) {
      triggerVibration(); 
      setItems(prev => [lastDeletedItem, ...prev]);
      setLastDeletedItem(null);
      if (undoTimeoutRef.current) clearTimeout(undoTimeoutRef.current);
    }
  }, [lastDeletedItem, triggerVibration]);

  const handleClearList = useCallback(() => {
    if (!clearSelection) return;
    triggerVibration();

    setItems(prev => {
      if (clearSelection === 'all') return [];
      if (clearSelection === 'purchased') return prev.filter(i => !i.isPurchased || !i.isAvailable);
      if (clearSelection === 'unavailable') return prev.filter(i => i.isAvailable);
      return prev;
    });

    setClearSelection(null);
    setShowClearConfirm(false);
  }, [clearSelection, triggerVibration]);

  const sections = useMemo(() => {
    let filtered = items.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    const sortFn = (a: ShoppingItem, b: ShoppingItem) => {
      switch (settings.sortMode) {
        case SortMode.NameAZ:
          return a.name.localeCompare(b.name);
        case SortMode.PriceAsc:
          return (a.unitPrice * a.quantity) - (b.unitPrice * b.quantity);
        case SortMode.PriceDesc:
          return (b.unitPrice * b.quantity) - (a.unitPrice * a.quantity);
        case SortMode.Newest:
          return b.addedAt - a.addedAt;
        default:
          return 0;
      }
    };

    const available = filtered.filter(i => i.isAvailable && !i.isPurchased).sort(sortFn);
    const purchased = filtered.filter(i => i.isAvailable && i.isPurchased).sort(sortFn);
    const unavailable = filtered.filter(i => !i.isAvailable).sort(sortFn);

    return { available, purchased, unavailable };
  }, [items, searchTerm, settings.sortMode]);

  const totalValue = useMemo(() => {
    return items
      .filter(i => i.isAvailable)
      .reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0);
  }, [items]);

  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;
  const availableCount = items.filter(i => i.isAvailable).length;

  const textSizeClass = settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base';
  const titleSizeClass = settings.textSize === 'small' ? 'text-base' : settings.textSize === 'large' ? 'text-xl' : 'text-lg';

  const formatValue = (val: number) => {
    return val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  };

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${textSizeClass}`}>
      <Header 
        itemCount={items.length} 
        availableCount={availableCount}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
      />

      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {/* Input area */}
        <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
          <div className="flex gap-2">
            <div className="flex-1 relative">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que você precisa?"
                className="w-full px-4 py-3 rounded-xl border-gray-200 border bg-white focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
              />
            </div>

            <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner">
              <input
                type="number"
                inputMode="numeric"
                value={newItemQty}
                onChange={(e) => setNewItemQty(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="QTD"
                className="w-14 text-center bg-transparent py-3 text-sm font-bold text-gray-700 outline-none"
              />
              <button 
                onClick={addItem}
                className="h-full px-4 bg-blue-600 text-white active:bg-blue-700 transition-colors flex items-center justify-center border-l border-blue-500"
                aria-label="Adicionar item"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>
          </div>
          {feedback && (
            <p className="text-amber-600 text-[10px] mt-2 px-1 font-bold uppercase animate-pulse">
              {feedback}
            </p>
          )}
        </div>

        {/* Search area */}
        <div className="relative px-1">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Buscar item..."
            className="w-full bg-gray-100/50 border-none rounded-xl py-2 pl-10 pr-4 text-xs focus:ring-1 focus:ring-gray-200 transition-all outline-none"
          />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          {searchTerm && (
            <button 
              onClick={() => setSearchTerm('')}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          )}
        </div>

        <div className="flex items-center justify-between px-1">
          <span className="text-gray-500 text-[10px] font-bold uppercase tracking-widest">
            {searchTerm ? `Resultados: ${sections.available.length + sections.purchased.length + sections.unavailable.length}` : 'Sua Lista'}
          </span>
          <select 
            value={settings.sortMode}
            onChange={(e) => setSettings({...settings, sortMode: e.target.value as SortMode})}
            className="text-[10px] bg-transparent border-none text-blue-600 font-bold uppercase focus:ring-0 cursor-pointer tracking-wider"
          >
            <option value={SortMode.NameAZ}>A–Z</option>
            <option value={SortMode.PriceAsc}>$ Menor</option>
            <option value={SortMode.PriceDesc}>$ Maior</option>
            <option value={SortMode.Newest}>Recentes</option>
          </select>
        </div>

        <div className="space-y-6">
          {sections.available.length === 0 && sections.purchased.length === 0 && sections.unavailable.length === 0 ? (
            <div className="text-center py-12 opacity-40">
              <svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12 mx-auto mb-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
              </svg>
              <p className="text-xs uppercase font-bold tracking-widest">Nenhum item encontrado</p>
            </div>
          ) : (
            <>
              {sections.available.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-blue-500 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Para Comprar</span>
                  </div>
                  {sections.available.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                      currency={settings.currency}
                    />
                  ))}
                </div>
              )}

              {sections.purchased.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">No Carrinho</span>
                  </div>
                  {sections.purchased.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                      currency={settings.currency}
                    />
                  ))}
                </div>
              )}

              {sections.unavailable.length > 0 && (
                <div className="space-y-3">
                  <div className="flex items-center gap-2 px-1 opacity-70">
                    <span className="w-2 h-2 bg-gray-400 rounded-full"></span>
                    <span className="text-[10px] font-bold uppercase tracking-widest text-gray-500">Itens indisponíveis</span>
                  </div>
                  {sections.unavailable.map(item => (
                    <ItemCard 
                      key={item.id} 
                      item={item} 
                      onUpdate={(updates) => updateItem(item.id, updates)} 
                      onDelete={() => deleteItem(item.id)}
                      textSizeClass={textSizeClass}
                      titleSizeClass={titleSizeClass}
                      isHapticEnabled={settings.isHapticEnabled}
                      currency={settings.currency}
                    />
                  ))}
                </div>
              )}
            </>
          )}
        </div>
      </main>

      {lastDeletedItem && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] max-w-sm z-[80] animate-in slide-in-from-bottom duration-300">
          <div className="bg-gray-900 text-white px-4 py-3 rounded-2xl flex items-center justify-between shadow-xl">
            <span className="text-sm font-medium">Item removido: <b>{lastDeletedItem.name}</b></span>
            <button 
              onClick={undoDelete}
              className="text-blue-400 font-bold text-sm uppercase tracking-wider active:scale-90 transition-transform"
            >
              Desfazer
            </button>
          </div>
        </div>
      )}

      <button 
        onClick={() => setShowQuickView(true)}
        className="fixed bottom-24 right-4 w-12 h-12 bg-white shadow-lg border border-gray-100 rounded-full flex items-center justify-center text-blue-600 active:scale-90 transition-transform z-20"
        aria-label="Visualização rápida"
      >
        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
        </svg>
      </button>

      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-6 py-4 flex flex-col items-center shadow-[0_-4px_10px_rgba(0,0,0,0.03)] z-30 transition-colors ${budgetExceeded ? 'border-red-500 bg-red-50' : ''}`}>
        <div className="w-full flex justify-between items-center">
          <div className="flex flex-col">
            <span className={`font-medium text-xs uppercase tracking-widest ${budgetExceeded ? 'text-red-600' : 'text-gray-500'}`}>Total Estimado</span>
            {settings.isBudgetModeActive && (
              <span className="text-[10px] text-gray-400 font-bold uppercase">Orçamento: {settings.currency} {settings.budgetLimit.toFixed(2)}</span>
            )}
          </div>
          <span className={`font-bold transition-colors ${budgetExceeded ? 'text-red-600' : 'text-blue-600'} ${settings.textSize === 'large' ? 'text-2xl' : 'text-xl'}`}>
            {settings.currency} {formatValue(totalValue)}
          </span>
        </div>
        {budgetExceeded && (
          <p className="text-[10px] text-red-600 font-bold uppercase mt-1 tracking-tighter animate-pulse">
            Você ultrapassou seu orçamento
          </p>
        )}
      </footer>

      {showSettings && (
        <SettingsModal 
          settings={settings} 
          onUpdate={(s) => setSettings(s)} 
          onClose={() => setShowSettings(false)} 
        />
      )}
      {showQuickView && (
        <QuickView 
          items={items} 
          total={totalValue} 
          onClose={() => setShowQuickView(false)} 
          textSizeClass={textSizeClass}
          currency={settings.currency}
        />
      )}

      {/* Enhanced Clear Selection Modal */}
      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center p-0 sm:p-4 animate-in fade-in duration-200">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => { setShowClearConfirm(false); setClearSelection(null); }} />
          <div className="relative bg-white w-full max-w-sm rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-bottom duration-300">

            {clearSelection === null ? (
              <>
                <h2 className="text-xl font-bold text-gray-900 mb-2">O que deseja limpar?</h2>
                <p className="text-gray-500 text-sm mb-8 leading-relaxed">Selecione o grupo de itens que você deseja remover permanentemente.</p>
                <div className="space-y-3">
                  <button 
                    onClick={() => setClearSelection('purchased')}
                    disabled={items.filter(i => i.isPurchased && i.isAvailable).length === 0}
                    className="w-full py-4 px-6 bg-green-50 text-green-700 font-bold rounded-2xl active:bg-green-100 transition-colors flex items-center justify-between disabled:opacity-30 disabled:grayscale"
                  >
                    <span>Remover itens no carrinho</span>
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                    </svg>
                  </button>
                  <button 
                    onClick={() => setClearSelection('unavailable')}
                    disabled={items.filter(i => !i.isAvailable).length === 0}
                    className="w-full py-4 px-6 bg-amber-50 text-amber-700 font-bold rounded-2xl active:bg-amber-100 transition-colors flex items-center justify-between disabled:opacity-30 disabled:grayscale"
                  >
                    <span>Remover indisponíveis</span>
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                    </svg>
                  </button>
                  <button 
                    onClick={() => setClearSelection('all')}
                    disabled={items.length === 0}
                    className="w-full py-4 px-6 bg-red-50 text-red-700 font-bold rounded-2xl active:bg-red-100 transition-colors flex items-center justify-between disabled:opacity-30 disabled:grayscale"
                  >
                    <span>Remover TUDO</span>
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                  <button 
                    onClick={() => setShowClearConfirm(false)}
                    className="w-full py-4 text-gray-400 font-bold text-sm"
                  >
                    Cancelar
                  </button>
                </div>
              </>
            ) : (
              <div className="animate-in zoom-in-95 duration-200">
                <div className="w-16 h-16 bg-red-100 rounded-2xl flex items-center justify-center mx-auto mb-4">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-red-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                </div>
                <h2 className="text-xl font-bold text-gray-900 text-center mb-2">Tem certeza?</h2>
                <p className="text-gray-500 text-center text-sm mb-8 leading-relaxed">
                  {clearSelection === 'all' && 'Você está prestes a apagar todos os itens da sua lista.'}
                  {clearSelection === 'purchased' && 'Você removerá apenas os itens que já estão no carrinho.'}
                  {clearSelection === 'unavailable' && 'Você removerá apenas os itens marcados como indisponíveis.'}
                </p>
                <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={() => setClearSelection(null)}
                    className="py-4 bg-gray-100 text-gray-700 font-bold rounded-xl active:bg-gray-200 transition-colors"
                  >
                    Voltar
                  </button>
                  <button 
                    onClick={handleClearList}
                    className="py-4 bg-[#dc2626] text-white font-bold rounded-xl active:scale-95 transition-transform"
                  >
                    Confirmar
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

