import React, { useRef, useState, useEffect } from 'react';
import { ShoppingItem } from '../types';

interface ItemCardProps {
  item: ShoppingItem;
  onUpdate: (updates: Partial<ShoppingItem>) => void;
  onDelete: () => void;
  textSizeClass: string;
  titleSizeClass: string;
  currency: string;
}

export const ItemCard: React.FC<ItemCardProps> = ({ item, onUpdate, onDelete, textSizeClass, titleSizeClass, currency }) => {
  const timerRef = useRef<number | null>(null);

  const [displayPrice, setDisplayPrice] = useState(
    item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',')
  );

  useEffect(() => {
    const formatted = item.unitPrice === 0 ? '' : item.unitPrice.toString().replace('.', ',');
    const currentNumeric = parseFloat(displayPrice.replace(',', '.'));
    const isSameValue = isNaN(currentNumeric) ? item.unitPrice === 0 : currentNumeric === item.unitPrice;

    if (!isSameValue) {
      setDisplayPrice(formatted);
    }
  }, [item.unitPrice]);

  const handlePriceChange = (val: string) => {
    const cleanVal = val.replace(/[^0-9.,]/g, '');
    const parts = cleanVal.split(/[.,]/);
    if (parts.length > 2) return;

    setDisplayPrice(cleanVal);
    const normalized = cleanVal.replace(',', '.');
    const price = parseFloat(normalized);
    onUpdate({ unitPrice: isNaN(price) ? 0 : price });
  };

  const handleLongPressStart = () => {
    timerRef.current = window.setTimeout(() => {
    }, 800);
  };

  const handleLongPressEnd = () => {
    if (timerRef.current) clearTimeout(timerRef.current);
  };

  const total = item.unitPrice * item.quantity;

  return (
    <div 
      className={`bg-white rounded-2xl p-4 border border-gray-100 shadow-sm transition-all duration-300 relative overflow-hidden ${!item.isAvailable ? 'opacity-50 grayscale' : 'opacity-100'} ${item.isPurchased && item.isAvailable ? 'bg-green-50/30' : ''}`}
      onTouchStart={handleLongPressStart}
      onTouchEnd={handleLongPressEnd}
      onMouseDown={handleLongPressStart}
      onMouseUp={handleLongPressEnd}
    >
      <div className="flex flex-col gap-3">
        <div className="flex justify-between items-start gap-2">
          <div className="flex items-center gap-2 flex-1">
             {item.isAvailable && (
              <button 
                onClick={() => {
                  onUpdate({ isPurchased: !item.isPurchased });
                }}
                className={`shrink-0 p-1.5 rounded-lg transition-colors ${item.isPurchased ? 'text-green-600 bg-green-100' : 'text-gray-300 bg-gray-50 active:bg-blue-50'}`}
                aria-label={item.isPurchased ? "Remover do carrinho" : "Adicionar ao carrinho"}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
                </svg>
              </button>
            )}
            <h3 className={`font-bold flex-1 break-words transition-all ${titleSizeClass} ${!item.isAvailable ? 'line-through text-gray-400' : item.isPurchased ? 'text-green-700' : 'text-gray-900'}`}>
              {item.name}
            </h3>
          </div>

          <div className="flex items-center gap-3 shrink-0">
            <button 
              onClick={(e) => {
                e.stopPropagation();
                onDelete();
              }}
              className="p-1.5 text-gray-300 hover:text-red-500 active:text-red-600 transition-colors"
              aria-label="Excluir item"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
            <button 
              onClick={() => {
                onUpdate({ isAvailable: !item.isAvailable });
              }}
              className={`w-12 h-6 rounded-full transition-colors flex items-center px-1 ${item.isAvailable ? 'bg-blue-600' : 'bg-gray-300'}`}
            >
              <div className={`w-4 h-4 bg-white rounded-full transition-transform transform ${item.isAvailable ? 'translate-x-6' : 'translate-x-0'}`} />
            </button>
          </div>
        </div>

        <div className="flex items-center justify-between gap-2">
          <div className="flex items-center bg-gray-50 rounded-xl p-1 border border-gray-100">
            <button 
              onClick={() => {
                onUpdate({ quantity: Math.max(1, item.quantity - 1) });
              }}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              −
            </button>
            <span className="w-10 text-center font-bold text-gray-700">{item.quantity}</span>
            <button 
              onClick={() => {
                onUpdate({ quantity: item.quantity + 1 });
              }}
              className="w-10 h-10 flex items-center justify-center text-blue-600 font-bold active:bg-white rounded-lg transition-colors"
            >
              +
            </button>
          </div>

          <div className="flex-1 max-w-[130px]">
            <label className="text-[10px] text-gray-400 font-bold uppercase block mb-1 text-center">Preço Unitário</label>
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs font-medium">{currency}</span>
              <input
                type="text"
                inputMode="decimal"
                value={displayPrice}
                onChange={(e) => handlePriceChange(e.target.value)}
                placeholder="0,00"
                className="w-full pl-9 pr-3 py-2 bg-gray-50 border border-gray-100 rounded-xl text-right font-semibold text-gray-700 focus:ring-2 focus:ring-blue-500/40 focus:border-blue-500 focus:bg-white outline-none transition-all shadow-sm"
              />
            </div>
          </div>
        </div>

        <div className="pt-2 border-t border-gray-50 flex justify-between items-center">
          <span className="text-gray-400 text-xs font-medium uppercase tracking-tight">Subtotal</span>
          <span className={`font-bold transition-colors ${item.isPurchased && item.isAvailable ? 'text-green-600' : 'text-gray-900'} ${textSizeClass}`}>
            {currency} {total.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
