      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Extraia itens de mercado desta frase e retorne um array JSON [{name, quantity}]. Frase: "${text}"`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                quantity: { type: Type.NUMBER }
              },
              required: ["name", "quantity"]
            }
          }
        }
      });
      const parsed = JSON.parse(response.text || '[]');
      const newItems: ShoppingItem[] = parsed.map((item: any) => ({
        id: crypto.randomUUID(),
        name: item.name.charAt(0).toUpperCase() + item.name.slice(1),
        quantity: item.quantity || 1,
        unitPrice: 0,
        isAvailable: true,
        isPurchased: false,
        addedAt: Date.now()
      }));
      setItems(prev => [...newItems, ...prev]);
      setFeedback(`${newItems.length} itens adicionados!`);
    } catch (e) { setFeedback("Erro ao processar voz."); }
    finally { setIsProcessingVoice(false); setIsListening(false); }
  };

  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;
    if (items.find(i => i.name.toLowerCase() === name.toLowerCase())) {
      setFeedback('Item já na lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }
    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: parseInt(newItemQty) || 1,
      unitPrice: 0,
      isAvailable: true,
      isPurchased: false,
      addedAt: Date.now()
    };
    setItems(prev => [newItem, ...prev]);
    setNewItemName(''); setNewItemQty('');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, items]);

  const handleExport = useCallback((includePrice: boolean) => {
    if (items.length === 0) return;

    // 1. Separar e Ordenar Alfabeticamente
    const sortAlpha = (a: ShoppingItem, b: ShoppingItem) => a.name.localeCompare(b.name);

    const available = items.filter(i => i.isAvailable && !i.isPurchased).sort(sortAlpha);
    const purchased = items.filter(i => i.isAvailable && i.isPurchased).sort(sortAlpha);
    const unavailable = items.filter(i => !i.isAvailable).sort(sortAlpha);

    let text = `LISTA DE COMPRAS - ${new Date().toLocaleDateString('pt-BR')}\n\n`;

    const formatLine = (i: ShoppingItem) => {
      let line = `- [${i.quantity}un] ${i.name}`;
      if (includePrice && i.unitPrice > 0) {
        const total = (i.unitPrice * i.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
        line += ` (${settings.currency} ${total})`;
      }
      return line + '\n';
    };

    if (available.length > 0) {
      text += `=== PARA COMPRAR ===\n`;
      available.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (purchased.length > 0) {
      text += `=== NO CARRINHO ===\n`;
      purchased.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (unavailable.length > 0) {
      text += `=== INDISPONÍVEIS ===\n`;
      unavailable.forEach(i => text += formatLine(i));
    }

    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `SuperList_${new Date().toISOString().split('T')[0]}.txt`;
    link.click();
    URL.revokeObjectURL(url);
    setShowExportModal(false);
  }, [items, settings.currency]);

  const sections = useMemo(() => {
    let filtered = items.filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));
    const sortFn = (a: ShoppingItem, b: ShoppingItem) => {
      if (settings.sortMode === SortMode.NameAZ) return a.name.localeCompare(b.name);
      if (settings.sortMode === SortMode.Newest) return b.addedAt - a.addedAt;
      const valA = a.unitPrice * a.quantity;
      const valB = b.unitPrice * b.quantity;
      return settings.sortMode === SortMode.PriceAsc ? valA - valB : valB - valA;
    };
    return {
      available: filtered.filter(i => i.isAvailable && !i.isPurchased).sort(sortFn),
      purchased: filtered.filter(i => i.isAvailable && i.isPurchased).sort(sortFn),
      unavailable: filtered.filter(i => !i.isAvailable).sort(sortFn)
    };
  }, [items, searchTerm, settings.sortMode]);

  const totalValue = useMemo(() => items.filter(i => i.isAvailable).reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0), [items]);
  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base'}`}>
      <Header 
        itemCount={items.length} 
        availableCount={items.filter(i => i.isAvailable).length}
        purchasedCount={items.filter(i => i.isAvailable && i.isPurchased).length}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
        isViewMode={isViewMode}
        onToggleViewMode={() => setIsViewMode(!isViewMode)}
        onExport={() => setShowExportModal(true)}
      />

      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {!isViewMode && (
          <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
            <div className="flex gap-2">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que falta?"
                className="flex-1 px-4 py-3 rounded-xl border-gray-200 border bg-white outline-none focus:ring-2 focus:ring-blue-500"
              />
              <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner shrink-0">
                <input
                  type="number"
                  inputMode="numeric"
                  value={newItemQty}
                  onChange={(e) => setNewItemQty(e.target.value)}
                  placeholder="QTD"
                  className="w-12 text-center bg-transparent py-3 text-sm font-bold outline-none"
                />
                <button 
                  onClick={startVoiceCapture}
                  className={`h-full px-4 border-l border-gray-200 flex flex-col items-center justify-center gap-0.5 ${isListening ? 'text-red-500' : 'text-blue-600'}`}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                  <span className="text-[7px] font-black uppercase">Voz</span>
                </button>
                <button onClick={addItem} className="h-full px-4 bg-blue-600 text-white border-l border-blue-500"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg></button>
              </div>
            </div>
          </div>
        )}

        <div className="relative px-1">
          <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar..." className="w-full bg-gray-100/50 rounded-xl py-2 pl-10 pr-4 text-xs outline-none" />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="bg-white rounded-[2rem] p-4 border border-gray-100 shadow-sm">
          {Object.entries(sections).map(([key, list]) => list.length > 0 && (
            <div key={key} className="mb-6 last:mb-0">
              <div className="flex items-center gap-2 px-1 pb-2 opacity-70">
                <span className={`w-1.5 h-1.5 rounded-full ${key === 'available' ? 'bg-blue-500' : key === 'purchased' ? 'bg-green-500' : 'bg-yellow-400'}`}></span>
                <span className="text-[9px] font-bold uppercase tracking-widest text-gray-500">{key === 'available' ? 'Para Comprar' : key === 'purchased' ? 'No Carrinho' : 'Indisponíveis'}</span>
              </div>
              {list.map(item => (
                <ItemCard key={item.id} item={item} onUpdate={(u) => setItems(prev => prev.map(i => i.id === item.id ? {...i, ...u} : i))} onDelete={() => { setLastDeletedItem(item); setItems(prev => prev.filter(i => i.id !== item.id)); }} textSizeClass="" titleSizeClass="" currency={settings.currency} isViewMode={isViewMode} />
              ))}
            </div>
          ))}
        </div>
      </main>

      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t p-6 flex flex-col items-center z-30 ${budgetExceeded ? 'bg-red-50 border-red-500 text-red-600' : ''}`}>
        <div className="w-full flex justify-between items-center font-bold">
          <span className="text-xs uppercase tracking-widest">Total Estimado</span>
          <span className="text-xl">{settings.currency} {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
        </div>
      </footer>

      {showSettings && <SettingsModal settings={settings} onUpdate={setSettings} onClose={() => setShowSettings(false)} />}
      {showExportModal && <ExportModal onConfirm={handleExport} onClose={() => setShowExportModal(false)} />}
      {(isListening || isProcessingVoice) && <VoiceOverlay isListening={isListening} isProcessing={isProcessingVoice} transcript={voiceTranscript} onClose={() => { setIsListening(false); setIsProcessingVoice(false); }} />}

      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center animate-in fade-in">
          <div className="absolute inset-0 bg-black/60" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-t-3xl p-8">
            <h2 className="text-xl font-bold mb-8 text-center">Limpar Lista?</h2>
            <div className="space-y-3">
              <button onClick={() => { setItems([]); setShowClearConfirm(false); }} className="w-full py-4 bg-red-50 text-red-700 font-bold rounded-2xl">Remover Tudo</button>
              <button onClick={() => setShowClearConfirm(false)} className="w-full py-4 text-gray-400 font-bold">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, SortMode, AppSettings } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { SettingsModal } from './components/SettingsModal';
import { ExportModal } from './components/ExportModal';
import { VoiceOverlay } from './components/VoiceOverlay';
import { GoogleGenAI, Type } from "@google/genai";

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

type ClearSelection = 'all' | 'purchased' | 'unavailable' | null;

const App: React.FC = () => {
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    currency: '€',
  });
  const [isViewMode, setIsViewMode] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemQty, setNewItemQty] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  // Voice State
  const [isListening, setIsListening] = useState(false);
  const [isProcessingVoice, setIsProcessingVoice] = useState(false);
  const [voiceTranscript, setVoiceTranscript] = useState('');

  const [clearSelection, setClearSelection] = useState<ClearSelection>(null);
  const [showClearConfirm, setShowClearConfirm] = useState(false);
  const [lastDeletedItem, setLastDeletedItem] = useState<ShoppingItem | null>(null);
  const undoTimeoutRef = useRef<number | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    // Fix: Explicitly cast JSON.parse result to ShoppingItem[] to avoid 'unknown' type issues in strict environments
    if (savedItems) setItems(JSON.parse(savedItems) as ShoppingItem[]);
    // Fix: Explicitly cast JSON.parse result to Partial<AppSettings> to avoid spreading 'unknown' types
    if (savedSettings) setSettings(prev => ({ ...prev, ...(JSON.parse(savedSettings) as Partial<AppSettings>) }));
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(items)); }, [items]);
  useEffect(() => { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); }, [settings]);

  const startVoiceCapture = () => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!SpeechRecognition) {
      setFeedback("Voz não suportada neste navegador.");
      return;
    }
    const recognition = new SpeechRecognition();
    recognition.lang = 'pt-BR';
    recognition.interimResults = true;
    recognition.onstart = () => { setIsListening(true); setVoiceTranscript(''); };
    recognition.onresult = (event: any) => setVoiceTranscript(event.results[event.resultIndex][0].transcript);
    recognition.onerror = () => setIsListening(false);
    recognition.onend = () => {
      if (voiceTranscript.trim()) processVoice(voiceTranscript);
      else setIsListening(false);
    };
    recognition.start();
  };

  const processVoice = async (text: string) => {
    setIsProcessingVoice(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Extraia itens de mercado desta frase e retorne um array JSON [{name, quantity}]. Frase: "${text}"`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                name: { type: Type.STRING },
                quantity: { type: Type.NUMBER }
              },
              required: ["name", "quantity"]
            }
          }
        }
      });
      // Fix: Explicitly cast JSON.parse result to any[] to avoid 'unknown' type errors when calling .map
      const parsed = JSON.parse(response.text || '[]') as any[];
      const newItems: ShoppingItem[] = parsed.map((item: any) => ({
        id: crypto.randomUUID(),
        name: item.name.charAt(0).toUpperCase() + item.name.slice(1),
        quantity: item.quantity || 1,
        unitPrice: 0,
        isAvailable: true,
        isPurchased: false,
        addedAt: Date.now()
      }));
      setItems(prev => [...newItems, ...prev]);
      setFeedback(`${newItems.length} itens adicionados!`);
    } catch (e) { setFeedback("Erro ao processar voz."); }
    finally { setIsProcessingVoice(false); setIsListening(false); }
  };

  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;
    if (items.find(i => i.name.toLowerCase() === name.toLowerCase())) {
      setFeedback('Item já na lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }
    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: parseInt(newItemQty) || 1,
      unitPrice: 0,
      isAvailable: true,
      isPurchased: false,
      addedAt: Date.now()
    };
    setItems(prev => [newItem, ...prev]);
    setNewItemName(''); setNewItemQty('');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, items]);

  const handleExport = useCallback((includePrice: boolean) => {
    if (items.length === 0) return;

    // 1. Separar e Ordenar Alfabeticamente
    const sortAlpha = (a: ShoppingItem, b: ShoppingItem) => a.name.localeCompare(b.name);

    const available = items.filter(i => i.isAvailable && !i.isPurchased).sort(sortAlpha);
    const purchased = items.filter(i => i.isAvailable && i.isPurchased).sort(sortAlpha);
    const unavailable = items.filter(i => !i.isAvailable).sort(sortAlpha);

    let text = `LISTA DE COMPRAS - ${new Date().toLocaleDateString('pt-BR')}\n\n`;

    const formatLine = (i: ShoppingItem) => {
      let line = `- [${i.quantity}un] ${i.name}`;
      if (includePrice && i.unitPrice > 0) {
        const total = (i.unitPrice * i.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
        line += ` (${settings.currency} ${total})`;
      }
      return line + '\n';
    };

    if (available.length > 0) {
      text += `=== PARA COMPRAR ===\n`;
      available.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (purchased.length > 0) {
      text += `=== NO CARRINHO ===\n`;
      purchased.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (unavailable.length > 0) {
      text += `=== INDISPONÍVEIS ===\n`;
      unavailable.forEach(i => text += formatLine(i));
    }

    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `SuperList_${new Date().toISOString().split('T')[0]}.txt`;
    link.click();
    URL.revokeObjectURL(url);
    setShowExportModal(false);
  }, [items, settings.currency]);

  // Fix: Explicitly type useMemo return as Record<string, ShoppingItem[]> to ensure Object.entries results in typed arrays instead of unknown
  const sections = useMemo<Record<string, ShoppingItem[]>>(() => {
    let filtered = items.filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));
    const sortFn = (a: ShoppingItem, b: ShoppingItem) => {
      if (settings.sortMode === SortMode.NameAZ) return a.name.localeCompare(b.name);
      if (settings.sortMode === SortMode.Newest) return b.addedAt - a.addedAt;
      const valA = a.unitPrice * a.quantity;
      const valB = b.unitPrice * b.quantity;
      return settings.sortMode === SortMode.PriceAsc ? valA - valB : valB - valA;
    };
    return {
      available: filtered.filter(i => i.isAvailable && !i.isPurchased).sort(sortFn),
      purchased: filtered.filter(i => i.isAvailable && i.isPurchased).sort(sortFn),
      unavailable: filtered.filter(i => !i.isAvailable).sort(sortFn)
    };
  }, [items, searchTerm, settings.sortMode]);

  const totalValue = useMemo(() => items.filter(i => i.isAvailable).reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0), [items]);
  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base'}`}>
      <Header 
        itemCount={items.length} 
        availableCount={items.filter(i => i.isAvailable).length}
        purchasedCount={items.filter(i => i.isAvailable && i.isPurchased).length}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
        isViewMode={isViewMode}
        onToggleViewMode={() => setIsViewMode(!isViewMode)}
        onExport={() => setShowExportModal(true)}
      />

      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {!isViewMode && (
          <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
            <div className="flex gap-2">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que falta?"
                className="flex-1 px-4 py-3 rounded-xl border-gray-200 border bg-white outline-none focus:ring-2 focus:ring-blue-500"
              />
              <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner shrink-0">
                <input
                  type="number"
                  inputMode="numeric"
                  value={newItemQty}
                  onChange={(e) => setNewItemQty(e.target.value)}
                  placeholder="QTD"
                  className="w-12 text-center bg-transparent py-3 text-sm font-bold outline-none"
                />
                <button 
                  onClick={startVoiceCapture}
                  className={`h-full px-4 border-l border-gray-200 flex flex-col items-center justify-center gap-0.5 ${isListening ? 'text-red-500' : 'text-blue-600'}`}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                  <span className="text-[7px] font-black uppercase">Voz</span>
                </button>
                <button onClick={addItem} className="h-full px-4 bg-blue-600 text-white border-l border-blue-500"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg></button>
              </div>
            </div>
          </div>
        )}

        <div className="relative px-1">
          <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar..." className="w-full bg-gray-100/50 rounded-xl py-2 pl-10 pr-4 text-xs outline-none" />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="bg-white rounded-[2rem] p-4 border border-gray-100 shadow-sm">
          {Object.entries(sections).map(([key, list]) => list.length > 0 && (
            <div key={key} className="mb-6 last:mb-0">
              <div className="flex items-center gap-2 px-1 pb-2 opacity-70">
                <span className={`w-1.5 h-1.5 rounded-full ${key === 'available' ? 'bg-blue-500' : key === 'purchased' ? 'bg-green-500' : 'bg-yellow-400'}`}></span>
                <span className="text-[9px] font-bold uppercase tracking-widest text-gray-500">{key === 'available' ? 'Para Comprar' : key === 'purchased' ? 'No Carrinho' : 'Indisponíveis'}</span>
              </div>
              {list.map(item => (
                <ItemCard key={item.id} item={item} onUpdate={(u) => setItems(prev => prev.map(i => i.id === item.id ? {...i, ...u} : i))} onDelete={() => { setLastDeletedItem(item); setItems(prev => prev.filter(i => i.id !== item.id)); }} textSizeClass="" titleSizeClass="" currency={settings.currency} isViewMode={isViewMode} />
              ))}
            </div>
          ))}
        </div>
      </main>

      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t p-6 flex flex-col items-center z-30 ${budgetExceeded ? 'bg-red-50 border-red-500 text-red-600' : ''}`}>
        <div className="w-full flex justify-between items-center font-bold">
          <span className="text-xs uppercase tracking-widest">Total Estimado</span>
          <span className="text-xl">{settings.currency} {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
        </div>
      </footer>

      {showSettings && <SettingsModal settings={settings} onUpdate={setSettings} onClose={() => setShowSettings(false)} />}
      {showExportModal && <ExportModal onConfirm={handleExport} onClose={() => setShowExportModal(false)} />}
      {(isListening || isProcessingVoice) && <VoiceOverlay isListening={isListening} isProcessing={isProcessingVoice} transcript={voiceTranscript} onClose={() => { setIsListening(false); setIsProcessingVoice(false); }} />}

      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center animate-in fade-in">
          <div className="absolute inset-0 bg-black/60" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-t-3xl p-8">
            <h2 className="text-xl font-bold mb-8 text-center">Limpar Lista?</h2>
            <div className="space-y-3">
              <button onClick={() => { setItems([]); setShowClearConfirm(false); }} className="w-full py-4 bg-red-50 text-red-700 font-bold rounded-2xl">Remover Tudo</button>
              <button onClick={() => setShowClearConfirm(false)} className="w-full py-4 text-gray-400 font-bold">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

