      available: filtered.filter(i => i.isAvailable && !i.isPurchased).sort(sortFn),
      purchased: filtered.filter(i => i.isAvailable && i.isPurchased).sort(sortFn),
      unavailable: filtered.filter(i => !i.isAvailable).sort(sortFn)
