    const sortAlpha = (a: ShoppingItem, b: ShoppingItem) => a.name.localeCompare(b.name);

    const available = items.filter(i => i.isAvailable && !i.isPurchased).sort(sortAlpha);
    const purchased = items.filter(i => i.isAvailable && i.isPurchased).sort(sortAlpha);
    const unavailable = items.filter(i => !i.isAvailable).sort(sortAlpha);

    let text = `LISTA DE COMPRAS - ${new Date().toLocaleDateString('pt-BR')}\n\n`;

    const formatLine = (i: ShoppingItem) => {
      let line = `- [${i.quantity}un] ${i.name}`;
      if (includePrice && i.unitPrice > 0) {
        const total = (i.unitPrice * i.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
        line += ` (${settings.currency} ${total})`;
      }
      return line + '\n';
    };

    if (available.length > 0) {
      text += `=== PARA COMPRAR ===\n`;
      available.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (purchased.length > 0) {
      text += `=== NO CARRINHO ===\n`;
      purchased.forEach(i => text += formatLine(i));
      text += `\n`;
