                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que falta?"
                className="flex-1 px-4 py-3 rounded-xl border-gray-200 border bg-white outline-none focus:ring-2 focus:ring-blue-500"
              />
              <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner shrink-0">
                <input
                  type="number"
                  inputMode="numeric"
                  value={newItemQty}
                  onChange={(e) => setNewItemQty(e.target.value)}
                  placeholder="QTD"
                  className="w-12 text-center bg-transparent py-3 text-sm font-bold outline-none"
