              </div>
              {list.map(item => (
                <ItemCard 
                  key={item.id} 
                  item={item} 
                  onUpdate={(u) => setItems(prev => prev.map(i => i.id === item.id ? {...i, ...u} : i))} 
                  onDelete={() => setItems(prev => prev.filter(i => i.id !== item.id))} 
                  textSizeClass="" 
                  titleSizeClass="" 
                  currency={settings.currency} 
                  isViewMode={isViewMode} 
                />
              ))}
            </div>
          ))}
        </div>
      </main>

      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t p-6 flex flex-col items-center z-30 ${budgetExceeded ? 'bg-red-50 border-red-500 text-red-600' : ''}`}>
        <div className="w-full flex justify-between items-center font-bold">
          <span className="text-xs uppercase tracking-widest">Total Estimado</span>
          <span className="text-xl">{settings.currency} {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
        </div>
      </footer>

      {showSettings && <SettingsModal settings={settings} onUpdate={setSettings} onClose={() => setShowSettings(false)} />}
      {showExportModal && <ExportModal onConfirm={handleExport} onClose={() => setShowExportModal(false)} />}

      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center animate-in fade-in">
          <div className="absolute inset-0 bg-black/60" onClick={() => setShowClearConfirm(false)} />
