export enum SortMode {
  NameAZ = 'NameAZ',
  PriceAsc = 'PriceAsc',
  PriceDesc = 'PriceDesc',
  Newest = 'Newest'
}

export type FilterStatus = 'all' | 'pending' | 'purchased' | 'unavailable';

export interface ShoppingItem {
  id: string;
  name: string;
  quantity: number;
  unitPrice: number;
  isAvailable: boolean;
  isPurchased: boolean;
  addedAt: number;
}

export interface AppSettings {
  textSize: TextSize;
  sortMode: SortMode;
  isBudgetModeActive: boolean;
  budgetLimit: number;
  currency: string;
}

