import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, SortMode, AppSettings, FilterStatus } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { SettingsModal } from './components/SettingsModal';
import { ExportModal } from './components/ExportModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

const App: React.FC = () => {
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    currency: '€',
  });
  const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
  const [isViewMode, setIsViewMode] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemQty, setNewItemQty] = useState<string>(''); 
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const [showClearConfirm, setShowClearConfirm] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems) as ShoppingItem[]);
    if (savedSettings) setSettings(prev => ({ ...prev, ...(JSON.parse(savedSettings) as Partial<AppSettings>) }));
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(items)); }, [items]);
  useEffect(() => { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); }, [settings]);

  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;
    if (items.find(i => i.name.toLowerCase() === name.toLowerCase())) {
      setFeedback('Item já na lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const price = parseFloat(newItemPrice.replace(',', '.'));

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: parseInt(newItemQty) || 1,
      unitPrice: isNaN(price) ? 0 : price,
      isAvailable: true,
      isPurchased: false,
      addedAt: Date.now()
    };
    setItems(prev => [newItem, ...prev]);
    setNewItemName(''); 
    setNewItemQty('');
    setNewItemPrice('');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, newItemPrice, items]);

  const handleExport = useCallback((includePrice: boolean) => {
    if (items.length === 0) return;

    const sortAlpha = (a: ShoppingItem, b: ShoppingItem) => a.name.localeCompare(b.name);

    const available = items.filter(i => i.isAvailable && !i.isPurchased).sort(sortAlpha);
    const purchased = items.filter(i => i.isAvailable && i.isPurchased).sort(sortAlpha);
    const unavailable = items.filter(i => !i.isAvailable).sort(sortAlpha);

    let text = `LISTA DE COMPRAS - ${new Date().toLocaleDateString('pt-BR')}\n\n`;

    const formatLine = (i: ShoppingItem) => {
      let line = `- [${i.quantity}un] ${i.name}`;
      if (includePrice && i.unitPrice > 0) {
        const total = (i.unitPrice * i.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
        line += ` (${settings.currency} ${total})`;
      }
      return line + '\n';
    };

    if (available.length > 0) {
      text += `=== PARA COMPRAR ===\n`;
      available.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (purchased.length > 0) {
      text += `=== NO CARRINHO ===\n`;
      purchased.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (unavailable.length > 0) {
      text += `=== INDISPONÍVEIS ===\n`;
      unavailable.forEach(i => text += formatLine(i));
    }

    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `SuperList_${new Date().toISOString().split('T')[0]}.txt`;
    link.click();
    URL.revokeObjectURL(url);
    setShowExportModal(false);
  }, [items, settings.currency]);

  const sections = useMemo<Record<string, ShoppingItem[]>>(() => {
    let baseFiltered = items.filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));

    // Aplicar Filtro de Status
    if (filterStatus === 'pending') baseFiltered = baseFiltered.filter(i => i.isAvailable && !i.isPurchased);
    if (filterStatus === 'purchased') baseFiltered = baseFiltered.filter(i => i.isAvailable && i.isPurchased);
    if (filterStatus === 'unavailable') baseFiltered = baseFiltered.filter(i => !i.isAvailable);

    const sortFn = (a: ShoppingItem, b: ShoppingItem) => {
      if (settings.sortMode === SortMode.NameAZ) return a.name.localeCompare(b.name);
      if (settings.sortMode === SortMode.Newest) return b.addedAt - a.addedAt;
      const valA = a.unitPrice * a.quantity;
      const valB = b.unitPrice * b.quantity;
      return settings.sortMode === SortMode.PriceAsc ? valA - valB : valB - valA;
    };

    const grouped = {
      available: baseFiltered.filter(i => i.isAvailable && !i.isPurchased).sort(sortFn),
      purchased: baseFiltered.filter(i => i.isAvailable && i.isPurchased).sort(sortFn),
      unavailable: baseFiltered.filter(i => !i.isAvailable).sort(sortFn)
    };

    return grouped;
  }, [items, searchTerm, settings.sortMode, filterStatus]);

  const totalValue = useMemo(() => items.filter(i => i.isAvailable).reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0), [items]);
  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base'}`}>
      <Header 
        itemCount={items.length} 
        availableCount={items.filter(i => i.isAvailable && !i.isPurchased).length}
        purchasedCount={items.filter(i => i.isAvailable && i.isPurchased).length}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
        isViewMode={isViewMode}
        onToggleViewMode={() => setIsViewMode(!isViewMode)}
        onExport={() => setShowExportModal(true)}
        currentFilter={filterStatus}
        onFilterChange={setFilterStatus}
      />

      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {!isViewMode && (
          <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
            <div className="flex flex-col gap-2">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que falta?"
                className="w-full px-4 py-3 rounded-xl border-gray-200 border bg-white outline-none focus:ring-2 focus:ring-blue-500 font-medium"
              />
              <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner w-full">
                <div className="flex items-center flex-1 px-3">
                  <span className="text-[10px] font-bold text-gray-400 mr-1 uppercase">Qtd</span>
                  <input
                    type="number"
                    inputMode="numeric"
                    value={newItemQty}
                    onChange={(e) => setNewItemQty(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && addItem()}
                    placeholder="1"
                    className="w-full bg-transparent py-3 text-sm font-bold outline-none text-gray-700"
                  />
                </div>
                <div className="w-px h-6 bg-gray-200" />
                <div className="flex items-center flex-[1.5] px-3">
                  <span className="text-[10px] font-bold text-gray-400 mr-1 uppercase">{settings.currency}</span>
                  <input
                    type="text"
                    inputMode="decimal"
                    value={newItemPrice}
                    onChange={(e) => setNewItemPrice(e.target.value.replace(/[^0-9.,]/g, ''))}
                    onKeyDown={(e) => e.key === 'Enter' && addItem()}
                    placeholder="0,00"
                    className="w-full bg-transparent py-3 text-sm font-bold outline-none text-gray-700"
                  />
                </div>
                {/* Botão de Filtro Rápido - No local solicitado */}
                <button 
                  onClick={() => setFilterStatus(prev => prev === 'pending' ? 'all' : 'pending')}
                  className={`h-10 w-10 m-1 rounded-lg transition-all flex items-center justify-center shrink-0 active:scale-90 shadow-sm ${
                    filterStatus === 'pending' ? 'bg-green-600 text-white shadow-green-100' : 'bg-white text-gray-400 border border-gray-200'
                  }`}
                  title={filterStatus === 'pending' ? "Mostrando Pendentes" : "Filtrar Pendentes"}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                  </svg>
                </button>
              </div>
            </div>
            {feedback && <p className="text-amber-600 text-[10px] mt-1 px-1 font-bold uppercase">{feedback}</p>}
          </div>
        )}

        <div className="relative px-1">
          <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar na lista..." className="w-full bg-gray-100/50 rounded-xl py-2 pl-10 pr-4 text-xs outline-none" />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="bg-white rounded-[2rem] p-4 border border-gray-100 shadow-sm min-h-[100px]">
          {filterStatus !== 'all' && (
            <div className="px-2 pb-4 flex justify-between items-center animate-in fade-in slide-in-from-top-1">
              <span className="text-[10px] font-bold text-gray-400 uppercase">Filtrando por: {filterStatus === 'pending' ? 'Pendentes' : filterStatus === 'purchased' ? 'Comprados' : 'Indisponíveis'}</span>
              <button onClick={() => setFilterStatus('all')} className="text-[10px] font-bold text-blue-600 uppercase">Limpar Filtro</button>
            </div>
          )}

          {/* Fix: Added explicit type checking to prevent 'unknown' property access errors */}
          {(Object.entries(sections) as [string, ShoppingItem[]][]).map(([key, list]) => list && list.length > 0 && (
            <div key={key} className="mb-6 last:mb-0">
              <div className="flex items-center gap-2 px-1 pb-2 opacity-70">
                <span className={`w-1.5 h-1.5 rounded-full ${key === 'available' ? 'bg-blue-500' : key === 'purchased' ? 'bg-green-500' : 'bg-yellow-400'}`}></span>
                <span className="text-[9px] font-bold uppercase tracking-widest text-gray-500">{key === 'available' ? 'Para Comprar' : key === 'purchased' ? 'No Carrinho' : 'Indisponíveis'}</span>
              </div>
              {list.map(item => (
                <ItemCard 
                  key={item.id} 
                  item={item} 
                  onUpdate={(u) => setItems(prev => prev.map(i => i.id === item.id ? {...i, ...u} : i))} 
                  onDelete={() => setItems(prev => prev.filter(i => i.id !== item.id))} 
                  textSizeClass="" 
                  titleSizeClass="" 
                  currency={settings.currency} 
                  isViewMode={isViewMode} 
                />
              ))}
            </div>
          ))}
          {/* Fix: Added explicit casting to Object.values to avoid 'unknown' type errors */}
          {(Object.values(sections) as ShoppingItem[][]).every(l => l.length === 0) && (
            <div className="py-12 text-center">
               <p className="text-gray-400 text-sm font-medium">Nenhum item encontrado com este filtro.</p>
            </div>
          )}
        </div>
      </main>

      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t p-6 flex flex-col items-center z-30 ${budgetExceeded ? 'bg-red-50 border-red-500 text-red-600' : ''}`}>
        <div className="w-full flex justify-between items-center font-bold">
          <span className="text-xs uppercase tracking-widest">Total Estimado</span>
          <span className="text-xl">{settings.currency} {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
        </div>
      </footer>

      {showSettings && <SettingsModal settings={settings} onUpdate={setSettings} onClose={() => setShowSettings(false)} />}
      {showExportModal && <ExportModal onConfirm={handleExport} onClose={() => setShowExportModal(false)} />}

      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center animate-in fade-in">
          <div className="absolute inset-0 bg-black/60" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-t-3xl p-8">
            <h2 className="text-xl font-bold mb-8 text-center">Limpar Lista?</h2>
            <div className="space-y-3">
              <button onClick={() => { setItems([]); setShowClearConfirm(false); }} className="w-full py-4 bg-red-50 text-red-700 font-bold rounded-2xl">Remover Tudo</button>
              <button onClick={() => setShowClearConfirm(false)} className="w-full py-4 text-gray-400 font-bold">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, SortMode, AppSettings, FilterStatus } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { SettingsModal } from './components/SettingsModal';
import { ExportModal } from './components/ExportModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

const App: React.FC = () => {
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    currency: '€',
  });
  const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
  const [isViewMode, setIsViewMode] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemQty, setNewItemQty] = useState<string>(''); 
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const [showClearConfirm, setShowClearConfirm] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems) as ShoppingItem[]);
    if (savedSettings) setSettings(prev => ({ ...prev, ...(JSON.parse(savedSettings) as Partial<AppSettings>) }));
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(items)); }, [items]);
  useEffect(() => { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); }, [settings]);

  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;
    if (items.find(i => i.name.toLowerCase() === name.toLowerCase())) {
      setFeedback('Item já na lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const price = parseFloat(newItemPrice.replace(',', '.'));

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: parseInt(newItemQty) || 1,
      unitPrice: isNaN(price) ? 0 : price,
      isAvailable: true,
      isPurchased: false,
      addedAt: Date.now()
    };
    setItems(prev => [newItem, ...prev]);
    setNewItemName(''); 
    setNewItemQty('');
    setNewItemPrice('');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, newItemPrice, items]);

  const handleExport = useCallback((includePrice: boolean) => {
    if (items.length === 0) return;

    const sortAlpha = (a: ShoppingItem, b: ShoppingItem) => a.name.localeCompare(b.name);

    const available = items.filter(i => i.isAvailable && !i.isPurchased).sort(sortAlpha);
    const purchased = items.filter(i => i.isAvailable && i.isPurchased).sort(sortAlpha);
    const unavailable = items.filter(i => !i.isAvailable).sort(sortAlpha);

    let text = `LISTA DE COMPRAS - ${new Date().toLocaleDateString('pt-BR')}\n\n`;

    const formatLine = (i: ShoppingItem) => {
      let line = `- [${i.quantity}un] ${i.name}`;
      if (includePrice && i.unitPrice > 0) {
        const total = (i.unitPrice * i.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
        line += ` (${settings.currency} ${total})`;
      }
      return line + '\n';
    };

    if (available.length > 0) {
      text += `=== PARA COMPRAR ===\n`;
      available.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (purchased.length > 0) {
      text += `=== NO CARRINHO ===\n`;
      purchased.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (unavailable.length > 0) {
      text += `=== INDISPONÍVEIS ===\n`;
      unavailable.forEach(i => text += formatLine(i));
    }

    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `SuperList_${new Date().toISOString().split('T')[0]}.txt`;
    link.click();
    URL.revokeObjectURL(url);
    setShowExportModal(false);
  }, [items, settings.currency]);

  const sections = useMemo<Record<string, ShoppingItem[]>>(() => {
    let baseFiltered = items.filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));

    // Aplicar Filtro de Status
    if (filterStatus === 'pending') baseFiltered = baseFiltered.filter(i => i.isAvailable && !i.isPurchased);
    if (filterStatus === 'purchased') baseFiltered = baseFiltered.filter(i => i.isAvailable && i.isPurchased);
    if (filterStatus === 'unavailable') baseFiltered = baseFiltered.filter(i => !i.isAvailable);

    const sortFn = (a: ShoppingItem, b: ShoppingItem) => {
      if (settings.sortMode === SortMode.NameAZ) return a.name.localeCompare(b.name);
      if (settings.sortMode === SortMode.Newest) return b.addedAt - a.addedAt;
      const valA = a.unitPrice * a.quantity;
      const valB = b.unitPrice * b.quantity;
      return settings.sortMode === SortMode.PriceAsc ? valA - valB : valB - valA;
    };

    const grouped = {
      available: baseFiltered.filter(i => i.isAvailable && !i.isPurchased).sort(sortFn),
      purchased: baseFiltered.filter(i => i.isAvailable && i.isPurchased).sort(sortFn),
      unavailable: baseFiltered.filter(i => !i.isAvailable).sort(sortFn)
    };

    return grouped;
  }, [items, searchTerm, settings.sortMode, filterStatus]);

  const totalValue = useMemo(() => items.filter(i => i.isAvailable).reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0), [items]);
  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  // Funções de limpeza
  const clearList = (type: 'all' | 'purchased' | 'unavailable') => {
    if (type === 'all') setItems([]);
    else if (type === 'purchased') setItems(prev => prev.filter(i => !(i.isAvailable && i.isPurchased)));
    else if (type === 'unavailable') setItems(prev => prev.filter(i => i.isAvailable));
    setShowClearConfirm(false);
  };

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base'}`}>
      <Header 
        itemCount={items.length} 
        availableCount={items.filter(i => i.isAvailable && !i.isPurchased).length}
        purchasedCount={items.filter(i => i.isAvailable && i.isPurchased).length}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
        isViewMode={isViewMode}
        onToggleViewMode={() => setIsViewMode(!isViewMode)}
        onExport={() => setShowExportModal(true)}
        currentFilter={filterStatus}
        onFilterChange={setFilterStatus}
      />

      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {!isViewMode && (
          <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
            <div className="flex flex-col gap-2">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que falta?"
                className="w-full px-4 py-3 rounded-xl border-gray-200 border bg-white outline-none focus:ring-2 focus:ring-blue-500 font-medium"
              />
              <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner w-full">
                <div className="flex items-center flex-1 px-3">
                  <span className="text-[10px] font-bold text-gray-400 mr-1 uppercase">Qtd</span>
                  <input
                    type="number"
                    inputMode="numeric"
                    value={newItemQty}
                    onChange={(e) => setNewItemQty(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && addItem()}
                    placeholder="1"
                    className="w-full bg-transparent py-3 text-sm font-bold outline-none text-gray-700"
                  />
                </div>
                <div className="w-px h-6 bg-gray-200" />
                <div className="flex items-center flex-[1.5] px-3">
                  <span className="text-[10px] font-bold text-gray-400 mr-1 uppercase">{settings.currency}</span>
                  <input
                    type="text"
                    inputMode="decimal"
                    value={newItemPrice}
                    onChange={(e) => setNewItemPrice(e.target.value.replace(/[^0-9.,]/g, ''))}
                    onKeyDown={(e) => e.key === 'Enter' && addItem()}
                    placeholder="0,00"
                    className="w-full bg-transparent py-3 text-sm font-bold outline-none text-gray-700"
                  />
                </div>
                <button 
                  onClick={() => setFilterStatus(prev => prev === 'pending' ? 'all' : 'pending')}
                  className={`h-10 w-10 m-1 rounded-lg transition-all flex items-center justify-center shrink-0 active:scale-90 shadow-sm ${
                    filterStatus === 'pending' ? 'bg-green-600 text-white shadow-green-100' : 'bg-white text-gray-400 border border-gray-200'
                  }`}
                  title={filterStatus === 'pending' ? "Mostrando Pendentes" : "Filtrar Pendentes"}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                  </svg>
                </button>
              </div>
            </div>
            {feedback && <p className="text-amber-600 text-[10px] mt-1 px-1 font-bold uppercase">{feedback}</p>}
          </div>
        )}

        <div className="relative px-1">
          <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar na lista..." className="w-full bg-gray-100/50 rounded-xl py-2 pl-10 pr-4 text-xs outline-none" />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="bg-white rounded-[2rem] p-4 border border-gray-100 shadow-sm min-h-[100px]">
          {filterStatus !== 'all' && (
            <div className="px-2 pb-4 flex justify-between items-center animate-in fade-in slide-in-from-top-1">
              <span className="text-[10px] font-bold text-gray-400 uppercase">Filtrando por: {filterStatus === 'pending' ? 'Pendentes' : filterStatus === 'purchased' ? 'Comprados' : 'Indisponíveis'}</span>
              <button onClick={() => setFilterStatus('all')} className="text-[10px] font-bold text-blue-600 uppercase">Limpar Filtro</button>
            </div>
          )}

          {(Object.entries(sections) as [string, ShoppingItem[]][]).map(([key, list]) => list && list.length > 0 && (
            <div key={key} className="mb-6 last:mb-0">
              <div className="flex items-center gap-2 px-1 pb-2 opacity-70">
                <span className={`w-1.5 h-1.5 rounded-full ${key === 'available' ? 'bg-blue-500' : key === 'purchased' ? 'bg-green-500' : 'bg-yellow-400'}`}></span>
                <span className="text-[9px] font-bold uppercase tracking-widest text-gray-500">{key === 'available' ? 'Para Comprar' : key === 'purchased' ? 'No Carrinho' : 'Indisponíveis'}</span>
              </div>
              {list.map(item => (
                <ItemCard 
                  key={item.id} 
                  item={item} 
                  onUpdate={(u) => setItems(prev => prev.map(i => i.id === item.id ? {...i, ...u} : i))} 
                  onDelete={() => setItems(prev => prev.filter(i => i.id !== item.id))} 
                  textSizeClass="" 
                  titleSizeClass="" 
                  currency={settings.currency} 
                  isViewMode={isViewMode} 
                />
              ))}
            </div>
          ))}
          {(Object.values(sections) as ShoppingItem[][]).every(l => l.length === 0) && (
            <div className="py-12 text-center">
               <p className="text-gray-400 text-sm font-medium">Nenhum item encontrado com este filtro.</p>
            </div>
          )}
        </div>
      </main>

      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t p-6 flex flex-col items-center z-30 ${budgetExceeded ? 'bg-red-50 border-red-500 text-red-600' : ''}`}>
        <div className="w-full flex justify-between items-center font-bold">
          <span className="text-xs uppercase tracking-widest">Total Estimado</span>
          <span className="text-xl">{settings.currency} {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
        </div>
      </footer>

      {showSettings && <SettingsModal settings={settings} onUpdate={setSettings} onClose={() => setShowSettings(false)} />}
      {showExportModal && <ExportModal onConfirm={handleExport} onClose={() => setShowExportModal(false)} />}

      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center animate-in fade-in">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="w-12 h-1.5 bg-gray-200 rounded-full mx-auto mb-6 sm:hidden" onClick={() => setShowClearConfirm(false)} />
            <h2 className="text-xl font-bold mb-8 text-center text-gray-900">Limpar Lista?</h2>
            <div className="space-y-3">
              <button 
                onClick={() => clearList('purchased')} 
                className="w-full py-4 bg-blue-50 text-blue-700 font-bold rounded-2xl active:scale-95 transition-transform flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
                Remover Comprados
              </button>
              <button 
                onClick={() => clearList('unavailable')} 
                className="w-full py-4 bg-amber-50 text-amber-700 font-bold rounded-2xl active:scale-95 transition-transform flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636" />
                </svg>
                Remover Indisponíveis
              </button>
              <button 
                onClick={() => clearList('all')} 
                className="w-full py-4 bg-red-50 text-red-700 font-bold rounded-2xl active:scale-95 transition-transform flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
                Remover TUDO
              </button>
              <button 
                onClick={() => setShowClearConfirm(false)} 
                className="w-full py-4 text-gray-400 font-bold"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { FilterStatus } from '../types';

interface HeaderProps {
  itemCount: number;
  availableCount: number;
  purchasedCount: number;
  unavailableCount: number;
  onOpenSettings: () => void;
  onClearList: () => void;
  isViewMode: boolean;
  onToggleViewMode: () => void;
  onExport?: () => void;
  currentFilter: FilterStatus;
  onFilterChange: (filter: FilterStatus) => void;
}

export const Header: React.FC<HeaderProps> = ({ 
  itemCount, 
  availableCount, 
  purchasedCount,
  unavailableCount,
  onOpenSettings, 
  onClearList,
  isViewMode,
  onToggleViewMode,
  onExport,
  currentFilter,
  onFilterChange
}) => {
  return (
    <header className="bg-white px-6 pt-6 pb-4 border-b border-gray-100 flex flex-col gap-4">
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            Minha Lista
          </h1>
          <p className="text-gray-400 text-sm">
            {isViewMode ? 'Modo Visualização' : 'Controle rápido'}
          </p>
        </div>
        <div className="flex gap-2">
          {isViewMode && (
            <button 
              onClick={onExport}
              className="w-10 h-10 flex items-center justify-center rounded-xl bg-blue-50 text-blue-600 active:scale-95 transition-all animate-in zoom-in duration-200"
              aria-label="Exportar Lista"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
              </svg>
            </button>
          )}

          <button 
            onClick={onToggleViewMode}
            className={`w-10 h-10 flex items-center justify-center rounded-xl transition-all ${
              isViewMode ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'bg-gray-50 text-gray-400'
            }`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
            </svg>
          </button>

          <button 
            onClick={onClearList}
            className="w-10 h-10 flex items-center justify-center text-[#dc2626] rounded-xl bg-red-50 active:bg-red-100 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>

          <button 
            onClick={onOpenSettings}
            className="w-10 h-10 flex items-center justify-center text-gray-400 rounded-xl bg-gray-50 active:bg-gray-100 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </button>
        </div>
      </div>
      <div className="flex flex-wrap gap-2">
        <button 
          onClick={() => onFilterChange('all')}
          className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-tight transition-all ${
            currentFilter === 'all' ? 'bg-gray-900 text-white shadow-md' : 'bg-gray-100 text-gray-600'
          }`}
        >
          Itens: {itemCount}
        </button>
        <button 
          onClick={() => onFilterChange('pending')}
          className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-tight transition-all ${
            currentFilter === 'pending' ? 'bg-green-600 text-white shadow-md' : 'bg-green-100 text-green-700'
          }`}
        >
          Disponíveis: {availableCount}
        </button>
        <button 
          onClick={() => onFilterChange('purchased')}
          className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-tight transition-all ${
            currentFilter === 'purchased' ? 'bg-blue-600 text-white shadow-md' : 'bg-blue-100 text-blue-700'
          }`}
        >
          Comprados: {purchasedCount}
        </button>
        <button 
          onClick={() => onFilterChange('unavailable')}
          className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-tight transition-all ${
            currentFilter === 'unavailable' ? 'bg-amber-600 text-white shadow-md' : 'bg-amber-100 text-amber-700'
          }`}
        >
          Indisponíveis: {unavailableCount}
        </button>
      </div>
    </header>
  );
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, SortMode, AppSettings, FilterStatus } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { SettingsModal } from './components/SettingsModal';
import { ExportModal } from './components/ExportModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

const App: React.FC = () => {
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    currency: '€',
  });
  const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
  const [isViewMode, setIsViewMode] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemQty, setNewItemQty] = useState<string>(''); 
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const [showClearConfirm, setShowClearConfirm] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems) as ShoppingItem[]);
    if (savedSettings) setSettings(prev => ({ ...prev, ...(JSON.parse(savedSettings) as Partial<AppSettings>) }));
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(items)); }, [items]);
  useEffect(() => { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); }, [settings]);

  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;
    if (items.find(i => i.name.toLowerCase() === name.toLowerCase())) {
      setFeedback('Item já na lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const price = parseFloat(newItemPrice.replace(',', '.'));

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: parseInt(newItemQty) || 1,
      unitPrice: isNaN(price) ? 0 : price,
      isAvailable: true,
      isPurchased: false,
      addedAt: Date.now()
    };
    setItems(prev => [newItem, ...prev]);
    setNewItemName(''); 
    setNewItemQty('');
    setNewItemPrice('');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, newItemPrice, items]);

  const handleExport = useCallback((includePrice: boolean) => {
    if (items.length === 0) return;

    const sortAlpha = (a: ShoppingItem, b: ShoppingItem) => a.name.localeCompare(b.name);

    const available = items.filter(i => i.isAvailable && !i.isPurchased).sort(sortAlpha);
    const purchased = items.filter(i => i.isAvailable && i.isPurchased).sort(sortAlpha);
    const unavailable = items.filter(i => !i.isAvailable).sort(sortAlpha);

    let text = `LISTA DE COMPRAS - ${new Date().toLocaleDateString('pt-BR')}\n\n`;

    const formatLine = (i: ShoppingItem) => {
      let line = `- [${i.quantity}un] ${i.name}`;
      if (includePrice && i.unitPrice > 0) {
        const total = (i.unitPrice * i.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
        line += ` (${settings.currency} ${total})`;
      }
      return line + '\n';
    };

    if (available.length > 0) {
      text += `=== PARA COMPRAR ===\n`;
      available.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (purchased.length > 0) {
      text += `=== NO CARRINHO ===\n`;
      purchased.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (unavailable.length > 0) {
      text += `=== INDISPONÍVEIS ===\n`;
      unavailable.forEach(i => text += formatLine(i));
    }

    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `SuperList_${new Date().toISOString().split('T')[0]}.txt`;
    link.click();
    URL.revokeObjectURL(url);
    setShowExportModal(false);
  }, [items, settings.currency]);

  const sections = useMemo<Record<string, ShoppingItem[]>>(() => {
    let baseFiltered = items.filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));

    // Aplicar Filtro de Status
    if (filterStatus === 'pending') baseFiltered = baseFiltered.filter(i => i.isAvailable && !i.isPurchased);
    if (filterStatus === 'purchased') baseFiltered = baseFiltered.filter(i => i.isAvailable && i.isPurchased);
    if (filterStatus === 'unavailable') baseFiltered = baseFiltered.filter(i => !i.isAvailable);

    const sortFn = (a: ShoppingItem, b: ShoppingItem) => {
      if (settings.sortMode === SortMode.NameAZ) return a.name.localeCompare(b.name);
      if (settings.sortMode === SortMode.Newest) return b.addedAt - a.addedAt;
      const valA = a.unitPrice * a.quantity;
      const valB = b.unitPrice * b.quantity;
      return settings.sortMode === SortMode.PriceAsc ? valA - valB : valB - valA;
    };

    const grouped = {
      available: baseFiltered.filter(i => i.isAvailable && !i.isPurchased).sort(sortFn),
      purchased: baseFiltered.filter(i => i.isAvailable && i.isPurchased).sort(sortFn),
      unavailable: baseFiltered.filter(i => !i.isAvailable).sort(sortFn)
    };

    return grouped;
  }, [items, searchTerm, settings.sortMode, filterStatus]);

  const totalValue = useMemo(() => items.filter(i => i.isAvailable).reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0), [items]);
  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  // Funções de limpeza
  const clearList = (type: 'all' | 'purchased' | 'unavailable') => {
    if (type === 'all') setItems([]);
    else if (type === 'purchased') setItems(prev => prev.filter(i => !(i.isAvailable && i.isPurchased)));
    else if (type === 'unavailable') setItems(prev => prev.filter(i => i.isAvailable));
    setShowClearConfirm(false);
  };

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base'}`}>
      <Header 
        itemCount={items.length} 
        availableCount={items.filter(i => i.isAvailable && !i.isPurchased).length}
        purchasedCount={items.filter(i => i.isAvailable && i.isPurchased).length}
        unavailableCount={items.filter(i => !i.isAvailable).length}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
        isViewMode={isViewMode}
        onToggleViewMode={() => setIsViewMode(!isViewMode)}
        onExport={() => setShowExportModal(true)}
        currentFilter={filterStatus}
        onFilterChange={setFilterStatus}
      />

      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {!isViewMode && (
          <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
            <div className="flex flex-col gap-2">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que falta?"
                className="w-full px-4 py-3 rounded-xl border-gray-200 border bg-white outline-none focus:ring-2 focus:ring-blue-500 font-medium"
              />
              <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner w-full">
                <div className="flex items-center flex-1 px-3">
                  <span className="text-[10px] font-bold text-gray-400 mr-1 uppercase">Qtd</span>
                  <input
                    type="number"
                    inputMode="numeric"
                    value={newItemQty}
                    onChange={(e) => setNewItemQty(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && addItem()}
                    placeholder="1"
                    className="w-full bg-transparent py-3 text-sm font-bold outline-none text-gray-700"
                  />
                </div>
                <div className="w-px h-6 bg-gray-200" />
                <div className="flex items-center flex-[1.5] px-3">
                  <span className="text-[10px] font-bold text-gray-400 mr-1 uppercase">{settings.currency}</span>
                  <input
                    type="text"
                    inputMode="decimal"
                    value={newItemPrice}
                    onChange={(e) => setNewItemPrice(e.target.value.replace(/[^0-9.,]/g, ''))}
                    onKeyDown={(e) => e.key === 'Enter' && addItem()}
                    placeholder="0,00"
                    className="w-full bg-transparent py-3 text-sm font-bold outline-none text-gray-700"
                  />
                </div>
                <button 
                  onClick={() => setFilterStatus(prev => prev === 'pending' ? 'all' : 'pending')}
                  className={`h-10 w-10 m-1 rounded-lg transition-all flex items-center justify-center shrink-0 active:scale-90 shadow-sm ${
                    filterStatus === 'pending' ? 'bg-green-600 text-white shadow-green-100' : 'bg-white text-gray-400 border border-gray-200'
                  }`}
                  title={filterStatus === 'pending' ? "Mostrando Pendentes" : "Filtrar Pendentes"}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
                  </svg>
                </button>
              </div>
            </div>
            {feedback && <p className="text-amber-600 text-[10px] mt-1 px-1 font-bold uppercase">{feedback}</p>}
          </div>
        )}

        <div className="relative px-1">
          <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar na lista..." className="w-full bg-gray-100/50 rounded-xl py-2 pl-10 pr-4 text-xs outline-none" />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="bg-white rounded-[2rem] p-4 border border-gray-100 shadow-sm min-h-[100px]">
          {filterStatus !== 'all' && (
            <div className="px-2 pb-4 flex justify-between items-center animate-in fade-in slide-in-from-top-1">
              <span className="text-[10px] font-bold text-gray-400 uppercase">Filtrando por: {filterStatus === 'pending' ? 'Pendentes' : filterStatus === 'purchased' ? 'Comprados' : 'Indisponíveis'}</span>
              <button onClick={() => setFilterStatus('all')} className="text-[10px] font-bold text-blue-600 uppercase">Limpar Filtro</button>
            </div>
          )}

          {(Object.entries(sections) as [string, ShoppingItem[]][]).map(([key, list]) => list && list.length > 0 && (
            <div key={key} className="mb-6 last:mb-0">
              <div className="flex items-center gap-2 px-1 pb-2 opacity-70">
                <span className={`w-1.5 h-1.5 rounded-full ${key === 'available' ? 'bg-blue-500' : key === 'purchased' ? 'bg-green-500' : 'bg-yellow-400'}`}></span>
                <span className="text-[9px] font-bold uppercase tracking-widest text-gray-500">{key === 'available' ? 'Para Comprar' : key === 'purchased' ? 'No Carrinho' : 'Indisponíveis'}</span>
              </div>
              {list.map(item => (
                <ItemCard 
                  key={item.id} 
                  item={item} 
                  onUpdate={(u) => setItems(prev => prev.map(i => i.id === item.id ? {...i, ...u} : i))} 
                  onDelete={() => setItems(prev => prev.filter(i => i.id !== item.id))} 
                  textSizeClass="" 
                  titleSizeClass="" 
                  currency={settings.currency} 
                  isViewMode={isViewMode} 
                />
              ))}
            </div>
          ))}
          {(Object.values(sections) as ShoppingItem[][]).every(l => l.length === 0) && (
            <div className="py-12 text-center">
               <p className="text-gray-400 text-sm font-medium">Nenhum item encontrado com este filtro.</p>
            </div>
          )}
        </div>
      </main>

      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t p-6 flex flex-col items-center z-30 ${budgetExceeded ? 'bg-red-50 border-red-500 text-red-600' : ''}`}>
        <div className="w-full flex justify-between items-center font-bold">
          <span className="text-xs uppercase tracking-widest">Total Estimado</span>
          <span className="text-xl">{settings.currency} {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
        </div>
      </footer>

      {showSettings && <SettingsModal settings={settings} onUpdate={setSettings} onClose={() => setShowSettings(false)} />}
      {showExportModal && <ExportModal onConfirm={handleExport} onClose={() => setShowExportModal(false)} />}

      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center animate-in fade-in">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="w-12 h-1.5 bg-gray-200 rounded-full mx-auto mb-6 sm:hidden" onClick={() => setShowClearConfirm(false)} />
            <h2 className="text-xl font-bold mb-8 text-center text-gray-900">Limpar Lista?</h2>
            <div className="space-y-3">
              <button 
                onClick={() => clearList('purchased')} 
                className="w-full py-4 bg-blue-50 text-blue-700 font-bold rounded-2xl active:scale-95 transition-transform flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
                Remover Comprados
              </button>
              <button 
                onClick={() => clearList('unavailable')} 
                className="w-full py-4 bg-amber-50 text-amber-700 font-bold rounded-2xl active:scale-95 transition-transform flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636" />
                </svg>
                Remover Indisponíveis
              </button>
              <button 
                onClick={() => clearList('all')} 
                className="w-full py-4 bg-red-50 text-red-700 font-bold rounded-2xl active:scale-95 transition-transform flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
                Remover TUDO
              </button>
              <button 
                onClick={() => setShowClearConfirm(false)} 
                className="w-full py-4 text-gray-400 font-bold"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { FilterStatus } from '../types';

interface HeaderProps {
  itemCount: number;
  availableCount: number;
  purchasedCount: number;
  unavailableCount: number;
  onOpenSettings: () => void;
  onClearList: () => void;
  isViewMode: boolean;
  onToggleViewMode: () => void;
  onExport?: () => void;
  currentFilter: FilterStatus;
  onFilterChange: (filter: FilterStatus) => void;
}

export const Header: React.FC<HeaderProps> = ({ 
  itemCount, 
  availableCount, 
  purchasedCount,
  unavailableCount,
  onOpenSettings, 
  onClearList,
  isViewMode,
  onToggleViewMode,
  onExport,
  currentFilter,
  onFilterChange
}) => {
  return (
    <header className="bg-white px-6 pt-6 pb-4 border-b border-gray-100 flex flex-col gap-4">
      <div className="flex justify-between items-start">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
            Minha Lista
          </h1>
          <p className="text-gray-400 text-sm">
            {isViewMode ? 'Modo Visualização' : 'Controle rápido'}
          </p>
        </div>
        <div className="flex gap-2">
          {isViewMode && (
            <button 
              onClick={onExport}
              className="w-10 h-10 flex items-center justify-center rounded-xl bg-blue-50 text-blue-600 active:scale-95 transition-all animate-in zoom-in duration-200"
              aria-label="Exportar Lista"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
              </svg>
            </button>
          )}

          <button 
            onClick={onToggleViewMode}
            className={`w-10 h-10 flex items-center justify-center rounded-xl transition-all ${
              isViewMode ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'bg-gray-50 text-gray-400'
            }`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
            </svg>
          </button>

          <button 
            onClick={onClearList}
            className="w-10 h-10 flex items-center justify-center text-[#dc2626] rounded-xl bg-red-50 active:bg-red-100 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>

          <button 
            onClick={onOpenSettings}
            className="w-10 h-10 flex items-center justify-center text-gray-400 rounded-xl bg-gray-50 active:bg-gray-100 transition-colors"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </button>
        </div>
      </div>

      {/* Container ajustado para rolagem horizontal e sem wrap */}
      <div className="flex overflow-x-auto no-scrollbar gap-2 -mx-2 px-2 pb-1">
        <button 
          onClick={() => onFilterChange('all')}
          className={`whitespace-nowrap px-2.5 py-1.5 rounded-full text-[9px] font-bold uppercase tracking-tight transition-all shrink-0 ${
            currentFilter === 'all' ? 'bg-gray-900 text-white shadow-md' : 'bg-gray-100 text-gray-600'
          }`}
        >
          Itens: {itemCount}
        </button>
        <button 
          onClick={() => onFilterChange('pending')}
          className={`whitespace-nowrap px-2.5 py-1.5 rounded-full text-[9px] font-bold uppercase tracking-tight transition-all shrink-0 ${
            currentFilter === 'pending' ? 'bg-green-600 text-white shadow-md' : 'bg-green-100 text-green-700'
          }`}
        >
          Disponíveis: {availableCount}
        </button>
        <button 
          onClick={() => onFilterChange('purchased')}
          className={`whitespace-nowrap px-2.5 py-1.5 rounded-full text-[9px] font-bold uppercase tracking-tight transition-all shrink-0 ${
            currentFilter === 'purchased' ? 'bg-blue-600 text-white shadow-md' : 'bg-blue-100 text-blue-700'
          }`}
        >
          Comprados: {purchasedCount}
        </button>
        <button 
          onClick={() => onFilterChange('unavailable')}
          className={`whitespace-nowrap px-2.5 py-1.5 rounded-full text-[9px] font-bold uppercase tracking-tight transition-all shrink-0 ${
            currentFilter === 'unavailable' ? 'bg-amber-600 text-white shadow-md' : 'bg-amber-100 text-amber-700'
          }`}
        >
          Indisponíveis: {unavailableCount}
        </button>
      </div>
    </header>
  );
};

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { ShoppingItem, SortMode, AppSettings, FilterStatus } from './types';
import { Header } from './components/Header';
import { ItemCard } from './components/ItemCard';
import { SettingsModal } from './components/SettingsModal';
import { ExportModal } from './components/ExportModal';

const STORAGE_KEY = 'superlist_data';
const SETTINGS_KEY = 'superlist_settings';

const App: React.FC = () => {
  const [items, setItems] = useState<ShoppingItem[]>([]);
  const [settings, setSettings] = useState<AppSettings>({
    textSize: 'medium',
    sortMode: SortMode.NameAZ,
    isBudgetModeActive: false,
    budgetLimit: 0,
    currency: '€',
  });
  const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
  const [isViewMode, setIsViewMode] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [newItemQty, setNewItemQty] = useState<string>(''); 
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<string | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);

  const [showClearConfirm, setShowClearConfirm] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const savedItems = localStorage.getItem(STORAGE_KEY);
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    if (savedItems) setItems(JSON.parse(savedItems) as ShoppingItem[]);
    if (savedSettings) setSettings(prev => ({ ...prev, ...(JSON.parse(savedSettings) as Partial<AppSettings>) }));
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(items)); }, [items]);
  useEffect(() => { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); }, [settings]);

  const addItem = useCallback(() => {
    const name = newItemName.trim();
    if (!name) return;
    if (items.find(i => i.name.toLowerCase() === name.toLowerCase())) {
      setFeedback('Item já na lista');
      setTimeout(() => setFeedback(null), 2000);
      return;
    }

    const price = parseFloat(newItemPrice.replace(',', '.'));

    const newItem: ShoppingItem = {
      id: crypto.randomUUID(),
      name: name.charAt(0).toUpperCase() + name.slice(1),
      quantity: parseInt(newItemQty) || 1,
      unitPrice: isNaN(price) ? 0 : price,
      isAvailable: true,
      isPurchased: false,
      addedAt: Date.now()
    };
    setItems(prev => [newItem, ...prev]);
    setNewItemName(''); 
    setNewItemQty('');
    setNewItemPrice('');
    inputRef.current?.focus();
  }, [newItemName, newItemQty, newItemPrice, items]);

  const handleExport = useCallback((includePrice: boolean) => {
    if (items.length === 0) return;

    const sortAlpha = (a: ShoppingItem, b: ShoppingItem) => a.name.localeCompare(b.name);

    const available = items.filter(i => i.isAvailable && !i.isPurchased).sort(sortAlpha);
    const purchased = items.filter(i => i.isAvailable && i.isPurchased).sort(sortAlpha);
    const unavailable = items.filter(i => !i.isAvailable).sort(sortAlpha);

    let text = `LISTA DE COMPRAS - ${new Date().toLocaleDateString('pt-BR')}\n\n`;

    const formatLine = (i: ShoppingItem) => {
      let line = `- [${i.quantity}un] ${i.name}`;
      if (includePrice && i.unitPrice > 0) {
        const total = (i.unitPrice * i.quantity).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
        line += ` (${settings.currency} ${total})`;
      }
      return line + '\n';
    };

    if (available.length > 0) {
      text += `=== PARA COMPRAR ===\n`;
      available.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (purchased.length > 0) {
      text += `=== NO CARRINHO ===\n`;
      purchased.forEach(i => text += formatLine(i));
      text += `\n`;
    }

    if (unavailable.length > 0) {
      text += `=== INDISPONÍVEIS ===\n`;
      unavailable.forEach(i => text += formatLine(i));
    }

    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `SuperList_${new Date().toISOString().split('T')[0]}.txt`;
    link.click();
    URL.revokeObjectURL(url);
    setShowExportModal(false);
  }, [items, settings.currency]);

  const sections = useMemo<Record<string, ShoppingItem[]>>(() => {
    let baseFiltered = items.filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));

    // Aplicar Filtro de Status
    if (filterStatus === 'pending') baseFiltered = baseFiltered.filter(i => i.isAvailable && !i.isPurchased);
    if (filterStatus === 'purchased') baseFiltered = baseFiltered.filter(i => i.isAvailable && i.isPurchased);
    if (filterStatus === 'unavailable') baseFiltered = baseFiltered.filter(i => !i.isAvailable);

    const sortFn = (a: ShoppingItem, b: ShoppingItem) => {
      if (settings.sortMode === SortMode.NameAZ) return a.name.localeCompare(b.name);
      if (settings.sortMode === SortMode.Newest) return b.addedAt - a.addedAt;
      const valA = a.unitPrice * a.quantity;
      const valB = b.unitPrice * b.quantity;
      return settings.sortMode === SortMode.PriceAsc ? valA - valB : valB - valA;
    };

    const grouped = {
      available: baseFiltered.filter(i => i.isAvailable && !i.isPurchased).sort(sortFn),
      purchased: baseFiltered.filter(i => i.isAvailable && i.isPurchased).sort(sortFn),
      unavailable: baseFiltered.filter(i => !i.isAvailable).sort(sortFn)
    };

    return grouped;
  }, [items, searchTerm, settings.sortMode, filterStatus]);

  const totalValue = useMemo(() => items.filter(i => i.isAvailable).reduce((acc, curr) => acc + (curr.unitPrice * curr.quantity), 0), [items]);
  const budgetExceeded = settings.isBudgetModeActive && totalValue > settings.budgetLimit;

  // Funções de limpeza
  const clearList = (type: 'all' | 'purchased' | 'unavailable') => {
    if (type === 'all') setItems([]);
    else if (type === 'purchased') setItems(prev => prev.filter(i => !(i.isAvailable && i.isPurchased)));
    else if (type === 'unavailable') setItems(prev => prev.filter(i => i.isAvailable));
    setShowClearConfirm(false);
  };

  return (
    <div className={`min-h-screen flex flex-col pb-24 ${settings.textSize === 'small' ? 'text-sm' : settings.textSize === 'large' ? 'text-lg' : 'text-base'}`}>
      <Header 
        itemCount={items.length} 
        availableCount={items.filter(i => i.isAvailable && !i.isPurchased).length}
        purchasedCount={items.filter(i => i.isAvailable && i.isPurchased).length}
        unavailableCount={items.filter(i => !i.isAvailable).length}
        onOpenSettings={() => setShowSettings(true)}
        onClearList={() => setShowClearConfirm(true)}
        isViewMode={isViewMode}
        onToggleViewMode={() => setIsViewMode(!isViewMode)}
        onExport={() => setShowExportModal(true)}
        currentFilter={filterStatus}
        onFilterChange={setFilterStatus}
      />

      <main className="flex-1 px-4 py-2 space-y-4 max-w-lg mx-auto w-full">
        {!isViewMode && (
          <div className="sticky top-2 z-10 bg-white/80 backdrop-blur-md p-3 rounded-2xl shadow-sm border border-gray-100 mb-2">
            <div className="flex flex-col gap-2">
              <input
                ref={inputRef}
                type="text"
                value={newItemName}
                onChange={(e) => setNewItemName(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addItem()}
                placeholder="O que falta?"
                className="w-full px-4 py-3 rounded-xl border-gray-200 border bg-white outline-none focus:ring-2 focus:ring-blue-500 font-medium"
              />
              <div className="flex items-center bg-gray-50 border border-gray-200 rounded-xl overflow-hidden shadow-inner w-full">
                <div className="flex items-center flex-1 px-3">
                  <span className="text-[10px] font-bold text-gray-400 mr-1 uppercase">Qtd</span>
                  <input
                    type="number"
                    inputMode="numeric"
                    value={newItemQty}
                    onChange={(e) => setNewItemQty(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && addItem()}
                    placeholder="1"
                    className="w-full bg-transparent py-3 text-sm font-bold outline-none text-gray-700"
                  />
                </div>
                <div className="w-px h-6 bg-gray-200" />
                <div className="flex items-center flex-[1.5] px-3">
                  <span className="text-[10px] font-bold text-gray-400 mr-1 uppercase">{settings.currency}</span>
                  <input
                    type="text"
                    inputMode="decimal"
                    value={newItemPrice}
                    onChange={(e) => setNewItemPrice(e.target.value.replace(/[^0-9.,]/g, ''))}
                    onKeyDown={(e) => e.key === 'Enter' && addItem()}
                    placeholder="0,00"
                    className="w-full bg-transparent py-3 text-sm font-bold outline-none text-gray-700"
                  />
                </div>
              </div>
            </div>
            {feedback && <p className="text-amber-600 text-[10px] mt-1 px-1 font-bold uppercase">{feedback}</p>}
          </div>
        )}

        <div className="relative px-1">
          <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar na lista..." className="w-full bg-gray-100/50 rounded-xl py-2 pl-10 pr-4 text-xs outline-none" />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="bg-white rounded-[2rem] p-4 border border-gray-100 shadow-sm min-h-[100px]">
          {filterStatus !== 'all' && (
            <div className="px-2 pb-4 flex justify-between items-center animate-in fade-in slide-in-from-top-1">
              <span className="text-[10px] font-bold text-gray-400 uppercase">Filtrando por: {filterStatus === 'pending' ? 'Pendentes' : filterStatus === 'purchased' ? 'Comprados' : 'Indisponíveis'}</span>
              <button onClick={() => setFilterStatus('all')} className="text-[10px] font-bold text-blue-600 uppercase">Limpar Filtro</button>
            </div>
          )}

          {(Object.entries(sections) as [string, ShoppingItem[]][]).map(([key, list]) => list && list.length > 0 && (
            <div key={key} className="mb-6 last:mb-0">
              <div className="flex items-center gap-2 px-1 pb-2 opacity-70">
                <span className={`w-1.5 h-1.5 rounded-full ${key === 'available' ? 'bg-blue-500' : key === 'purchased' ? 'bg-green-500' : 'bg-yellow-400'}`}></span>
                <span className="text-[9px] font-bold uppercase tracking-widest text-gray-500">{key === 'available' ? 'Para Comprar' : key === 'purchased' ? 'No Carrinho' : 'Indisponíveis'}</span>
              </div>
              {list.map(item => (
                <ItemCard 
                  key={item.id} 
                  item={item} 
                  onUpdate={(u) => setItems(prev => prev.map(i => i.id === item.id ? {...i, ...u} : i))} 
                  onDelete={() => setItems(prev => prev.filter(i => i.id !== item.id))} 
                  textSizeClass="" 
                  titleSizeClass="" 
                  currency={settings.currency} 
                  isViewMode={isViewMode} 
                />
              ))}
            </div>
          ))}
          {(Object.values(sections) as ShoppingItem[][]).every(l => l.length === 0) && (
            <div className="py-12 text-center">
               <p className="text-gray-400 text-sm font-medium">Nenhum item encontrado com este filtro.</p>
            </div>
          )}
        </div>
      </main>

      <footer className={`fixed bottom-0 left-0 right-0 bg-white border-t p-6 flex flex-col items-center z-30 ${budgetExceeded ? 'bg-red-50 border-red-500 text-red-600' : ''}`}>
        <div className="w-full flex justify-between items-center font-bold">
          <span className="text-xs uppercase tracking-widest">Total Estimado</span>
          <span className="text-xl">{settings.currency} {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
        </div>
      </footer>

      {showSettings && <SettingsModal settings={settings} onUpdate={setSettings} onClose={() => setShowSettings(false)} />}
      {showExportModal && <ExportModal onConfirm={handleExport} onClose={() => setShowExportModal(false)} />}

      {showClearConfirm && (
        <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center animate-in fade-in">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowClearConfirm(false)} />
          <div className="relative bg-white w-full max-w-sm rounded-t-[2.5rem] sm:rounded-[2.5rem] p-8 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="w-12 h-1.5 bg-gray-200 rounded-full mx-auto mb-6 sm:hidden" onClick={() => setShowClearConfirm(false)} />
            <h2 className="text-xl font-bold mb-8 text-center text-gray-900">Limpar Lista?</h2>
            <div className="space-y-3">
              <button 
                onClick={() => clearList('purchased')} 
                className="w-full py-4 bg-blue-50 text-blue-700 font-bold rounded-2xl active:scale-95 transition-transform flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
                Remover Comprados
              </button>
              <button 
                onClick={() => clearList('unavailable')} 
                className="w-full py-4 bg-amber-50 text-amber-700 font-bold rounded-2xl active:scale-95 transition-transform flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18.364 18.364A9 9 0 005.636 5.636m12.728 12.728A9 9 0 015.636 5.636" />
                </svg>
                Remover Indisponíveis
              </button>
              <button 
                onClick={() => clearList('all')} 
                className="w-full py-4 bg-red-50 text-red-700 font-bold rounded-2xl active:scale-95 transition-transform flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
                Remover TUDO
              </button>
              <button 
                onClick={() => setShowClearConfirm(false)} 
                className="w-full py-4 text-gray-400 font-bold"
              >
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import { FilterStatus } from '../types';

interface HeaderProps {
  itemCount: number;
  availableCount: number;
  purchasedCount: number;
  unavailableCount: number;
  onOpenSettings: () => void;
  onClearList: () => void;
  isViewMode: boolean;
  onToggleViewMode: () => void;
  onExport?: () => void;
  currentFilter: FilterStatus;
  onFilterChange: (filter: FilterStatus) => void;
}

export const Header: React.FC<HeaderProps> = ({ 
  itemCount, 
  availableCount, 
  purchasedCount,
  unavailableCount,
  onOpenSettings, 
  onClearList,
  isViewMode,
  onToggleViewMode,
  onExport,
  currentFilter,
  onFilterChange
